// GERADO por packages/report-renderer/gen_sources.py (não editar à mão).
// Fonte do renderer Python embutido como strings para o job do trigger
// escrever num sandbox E2B em runtime (evita rebuild de template).
// Regenerar: python gen_sources.py

export const RENDERER_SOURCES: Record<string, string> = {
  "docx_renderer.py": "\"\"\"Renderer DOCX (python-docx) do ReportModel \u2014 estilo \"dossie\".\n\nCasca de dossie: capa com codigo de documento + faixa de KPIs, rodape com\nclassificacao + docCode + numero de pagina, divisorias de PARTE. Marca\nconfiguravel por MSSP (meta.brand sobrescreve paleta/wordmark).\"\"\"\n\nfrom docx import Document\nfrom docx.shared import Pt, RGBColor, Inches, Emu\nfrom docx.enum.text import WD_ALIGN_PARAGRAPH\nfrom docx.enum.table import WD_TABLE_ALIGNMENT\nfrom docx.oxml.ns import qn\nfrom docx.oxml import OxmlElement, parse_xml\nimport os\n\nimport theme as T\nimport logo\n\n\ndef _rgb(h):\n    return RGBColor.from_string(h)\n\n\ndef _shade(cell, hexfill):\n    tcPr = cell._tc.get_or_add_tcPr()\n    shd = OxmlElement(\"w:shd\")\n    shd.set(qn(\"w:val\"), \"clear\")\n    shd.set(qn(\"w:fill\"), hexfill)\n    tcPr.append(shd)\n\n\ndef _set_font(r, name):\n    \"\"\"Define a familia do run em ascii+hAnsi+cs \u2014 garante IBM Plex em todo o\n    texto (ASCII, acentos pt-BR e scripts complexos), nao so no ASCII.\"\"\"\n    r.font.name = name\n    rpr = r._element.get_or_add_rPr()\n    rf = rpr.find(qn(\"w:rFonts\"))\n    if rf is None:\n        rf = OxmlElement(\"w:rFonts\")\n        rpr.append(rf)\n    for attr in (\"w:ascii\", \"w:hAnsi\", \"w:cs\"):\n        rf.set(qn(attr), name)\n\n\ndef _run(p, text, size=11, bold=False, color=T.INK, font=T.FONT_BODY):\n    r = p.add_run(str(text))\n    r.font.size = Pt(size)\n    r.font.bold = bold\n    _set_font(r, font)\n    r.font.color.rgb = _rgb(color)\n    return r\n\n\ndef _para(doc, text, size=11, bold=False, color=T.INK, after=6, align=None):\n    p = doc.add_paragraph()\n    if align is not None:\n        p.alignment = align\n    p.paragraph_format.space_after = Pt(after)\n    _run(p, text, size, bold, color)\n    return p\n\n\ndef _heading(doc, text, level=1):\n    p = doc.add_paragraph()\n    # Estilo de cabe\u00e7alho nomeado \u2192 entra no outline/navega\u00e7\u00e3o/TOC do Word.\n    # A formata\u00e7\u00e3o da marca (run abaixo) sobrep\u00f5e a apar\u00eancia do estilo.\n    try:\n        p.style = doc.styles[\"Heading 1\" if level == 1 else \"Heading 2\"]\n    except KeyError:\n        pass\n    p.paragraph_format.space_before = Pt(14)\n    p.paragraph_format.space_after = Pt(6)\n    _run(p, text, size=17 if level == 1 else 14, bold=True, color=T.PRIMARY,\n         font=T.FONT_DISPLAY)\n    pPr = p._p.get_or_add_pPr()\n    bdr = OxmlElement(\"w:pBdr\")\n    bottom = OxmlElement(\"w:bottom\")\n    bottom.set(qn(\"w:val\"), \"single\")\n    bottom.set(qn(\"w:sz\"), \"12\")\n    bottom.set(qn(\"w:space\"), \"4\")\n    bottom.set(qn(\"w:color\"), T.CORAL)\n    bdr.append(bottom)\n    pPr.append(bdr)\n    return p\n\n\ndef _clip(s, n):\n    s = str(s or \"\")\n    return s if len(s) <= n else s[: n - 1] + \"\u2026\"\n\n\n# Salvaguarda contra entradas patol\u00f3gicas; N\u00c3O trunca conte\u00fado real de achado.\n# DOCX pagina sozinho \u2014 corpo de achado/evid\u00eancia nunca \u00e9 cortado (regra do dossi\u00ea).\nBODY_SOFT_MAX = 200000\n\n\ndef _body(doc, text, size=11, bold=False, color=T.INK, after=6, font=None):\n    \"\"\"Par\u00e1grafo de corpo que preserva quebras de linha (\\\\n) e NUNCA trunca.\"\"\"\n    s = str(text or \"\")\n    if len(s) > BODY_SOFT_MAX:\n        s = s[:BODY_SOFT_MAX]\n    p = doc.add_paragraph()\n    p.paragraph_format.space_after = Pt(after)\n    r = p.add_run()\n    r.font.size = Pt(size)\n    r.font.bold = bold\n    _set_font(r, font or T.FONT_BODY)\n    r.font.color.rgb = _rgb(color)\n    parts = s.split(\"\\n\")\n    for i, ln in enumerate(parts):\n        if i:\n            r.add_break()\n        r.add_text(ln)\n    return p\n\n\ndef _apply_brand(meta):\n    brand = meta.get(\"brand\") or {}\n    if brand.get(\"primary\"):\n        T.PRIMARY = brand[\"primary\"]\n    if brand.get(\"accent\"):\n        T.CORAL = brand[\"accent\"]\n    if brand.get(\"wordmark\"):\n        T.WORDMARK = brand[\"wordmark\"]\n\n\ndef _add_page_field(p, size=8, color=None):\n    color = color or T.MUTED\n    fld = OxmlElement(\"w:fldSimple\")\n    fld.set(qn(\"w:instr\"), \"PAGE\")\n    run = OxmlElement(\"w:r\")\n    rpr = OxmlElement(\"w:rPr\")\n    rf = OxmlElement(\"w:rFonts\")  # sem isto o n\u00ba de p\u00e1gina cai p/ serifa\n    for attr in (\"w:ascii\", \"w:hAnsi\", \"w:cs\"):\n        rf.set(qn(attr), T.FONT_BODY)\n    rpr.append(rf)\n    sz = OxmlElement(\"w:sz\")\n    sz.set(qn(\"w:val\"), str(size * 2))\n    rpr.append(sz)\n    col = OxmlElement(\"w:color\")\n    col.set(qn(\"w:val\"), color)\n    rpr.append(col)\n    run.append(rpr)\n    t = OxmlElement(\"w:t\")\n    t.text = \"1\"\n    run.append(t)\n    fld.append(run)\n    p._p.append(fld)\n\n\ndef _setup_footer(doc, meta):\n    sec = doc.sections[0]\n    p = sec.footer.paragraphs[0]\n    p.text = \"\"\n    _run(p, meta.get(\"classification\", \"\"), size=8, color=T.MUTED)\n    _run(p, \"   \u00b7   \" + meta.get(\"docCode\", \"\") + \"   \u00b7   p\u00e1g. \", size=8,\n         color=T.MUTED)\n    _add_page_field(p)\n\n\ndef _stat_tiles(doc, stats):\n    stats = (stats or [])[:4]\n    if not stats:\n        return\n    t = doc.add_table(rows=2, cols=len(stats))\n    t.alignment = WD_TABLE_ALIGNMENT.CENTER\n    for j, s in enumerate(stats):\n        c0 = t.cell(0, j)\n        c0.text = \"\"\n        _shade(c0, T.SURFACE_ALT)\n        _run(c0.paragraphs[0], str(s.get(\"value\", \"\")), size=26, bold=True,\n             color=T.PRIMARY, font=T.FONT_DISPLAY)\n        c1 = t.cell(1, j)\n        c1.text = \"\"\n        _shade(c1, T.SURFACE_ALT)\n        _run(c1.paragraphs[0], str(s.get(\"label\", \"\")).upper(), size=9,\n             bold=True, color=T.MUTED)\n    doc.add_paragraph()\n\n\n# Namespaces OOXML p/ a \u00e2ncora de imagem flutuante (capa full-bleed).\n_WP_NS = \"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\"\n_A_NS = \"http://schemas.openxmlformats.org/drawingml/2006/main\"\n_R_NS = \"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"\n_PIC_NS = \"http://schemas.openxmlformats.org/drawingml/2006/picture\"\n\n\ndef _page_background(doc, img_path, pw_emu, ph_emu):\n    \"\"\"Imagem full-page ancorada \u00e0 P\u00c1GINA, ATR\u00c1S do texto (behindDoc + wrapNone).\n    No Word, relativeFrom=page + offset 0 = canto f\u00edsico da p\u00e1gina = full-bleed\n    real (independe das margens da se\u00e7\u00e3o); o par\u00e1grafo-portador fica na p\u00e1g. 1, ent\u00e3o\n    a arte s\u00f3 aparece na capa. OBS: o LibreOffice trata page como \u00e1rea de texto e\n    mostra margem branca \u2014 o alvo \u00e9 o Word (entreg\u00e1vel do cliente).\"\"\"\n    p = doc.add_paragraph()\n    run = p.add_run()\n    run.add_picture(img_path, width=Emu(int(pw_emu)), height=Emu(int(ph_emu)))\n    drawing = run._r.find(qn(\"w:drawing\"))\n    inline = drawing.find(qn(\"wp:inline\"))\n    graphic = inline.find(qn(\"a:graphic\"))\n    anchor = parse_xml(\n        f'<wp:anchor xmlns:wp=\"{_WP_NS}\" xmlns:a=\"{_A_NS}\" xmlns:r=\"{_R_NS}\" '\n        f'xmlns:pic=\"{_PIC_NS}\" behindDoc=\"1\" distT=\"0\" distB=\"0\" distL=\"0\" '\n        'distR=\"0\" simplePos=\"0\" locked=\"0\" layoutInCell=\"1\" allowOverlap=\"1\" '\n        'relativeHeight=\"0\">'\n        '<wp:simplePos x=\"0\" y=\"0\"/>'\n        '<wp:positionH relativeFrom=\"page\"><wp:posOffset>0</wp:posOffset>'\n        \"</wp:positionH>\"\n        '<wp:positionV relativeFrom=\"page\"><wp:posOffset>0</wp:posOffset>'\n        \"</wp:positionV>\"\n        f'<wp:extent cx=\"{int(pw_emu)}\" cy=\"{int(ph_emu)}\"/>'\n        '<wp:effectExtent l=\"0\" t=\"0\" r=\"0\" b=\"0\"/>'\n        \"<wp:wrapNone/>\"\n        '<wp:docPr id=\"1000\" name=\"CoverBackground\"/>'\n        \"<wp:cNvGraphicFramePr/>\"\n        \"</wp:anchor>\"\n    )\n    anchor.append(graphic)\n    drawing.remove(inline)\n    drawing.append(anchor)\n    p.paragraph_format.space_before = Pt(0)\n    p.paragraph_format.space_after = Pt(0)\n    return p\n\n\ndef _cover_stats_white(doc, stats):\n    \"\"\"Faixa de KPIs da capa full-bleed: texto branco, SEM sombreamento (c\u00e9lulas\n    transparentes deixam o navy do fundo aparecer).\"\"\"\n    stats = (stats or [])[:4]\n    if not stats:\n        return\n    t = doc.add_table(rows=2, cols=len(stats))\n    t.alignment = WD_TABLE_ALIGNMENT.LEFT\n    for j, s in enumerate(stats):\n        c0 = t.cell(0, j)\n        c0.text = \"\"\n        _run(c0.paragraphs[0], str(s.get(\"value\", \"\")), size=24, bold=True,\n             color=\"FFFFFF\", font=T.FONT_DISPLAY)\n        c1 = t.cell(1, j)\n        c1.text = \"\"\n        _run(c1.paragraphs[0], str(s.get(\"label\", \"\")).upper(), size=9,\n             bold=True, color=\"C9D3E6\")\n    doc.add_paragraph()\n\n\ndef _cover(doc, sec, meta):\n    brand = meta.get(\"brand\", {})\n    # Capa com arte da marca (coverImagePath) \u2192 FULL-BLEED real: a arte preenche a\n    # p\u00e1gina inteira (imagem flutuante behindDoc) e o texto branco fica por cima,\n    # como no PPTX/PDF. Ausente \u2192 capa program\u00e1tica clara (t\u00edtulo escuro).\n    cover = brand.get(\"coverImagePath\")\n    if not (cover and os.path.exists(cover)):\n        # Sem arte da marca \u2192 a capa NASCE navy (padr\u00e3o-ouro SYN), n\u00e3o clara:\n        # fundo navy full-page + t\u00edtulo/logo/KPIs em branco.\n        try:\n            cover = T.default_cover_bg()\n        except Exception:\n            cover = None\n    fullbleed = bool(cover and os.path.exists(cover))\n    if fullbleed:\n        secpg = doc.sections[0]\n        try:\n            fitted = T.cover_fit(cover, int(secpg.page_width),\n                                 int(secpg.page_height))\n            _page_background(doc, fitted, secpg.page_width, secpg.page_height)\n        except Exception:\n            fullbleed = False\n    # Wordmark (topo-esq): logo custom > logo Suricatoos (claro p/ navy full-bleed,\n    # escuro p/ capa clara) > texto.\n    used_logo = False\n    logo_path = brand.get(\"logoPath\")\n    if logo_path and os.path.exists(logo_path):\n        try:\n            doc.add_picture(logo_path, width=Inches(1.1))\n            used_logo = True\n        except Exception:\n            used_logo = False\n    if not used_logo and brand.get(\"wordmark\", \"\") == \"Suricatoos\":\n        lp = logo.write_logo(dark=fullbleed)\n        if lp and os.path.exists(lp):\n            try:\n                # Wordmark oficial Suricatoos (1600x274, ~5.84:1) \u2014 destaque de\n                # capa; largura generosa p/ o logotipo dominar o topo-esquerdo.\n                doc.add_picture(lp, width=Inches(2.6))\n                used_logo = True\n            except Exception:\n                used_logo = False\n    if not used_logo:\n        _para(doc, brand.get(\"wordmark\", T.WORDMARK), size=22, bold=True,\n              color=T.CORAL, align=WD_ALIGN_PARAGRAPH.LEFT)\n    title_color = \"FFFFFF\" if fullbleed else T.INK\n    muted_color = \"C9D3E6\" if fullbleed else T.MUTED\n    if fullbleed:\n        for _ in range(6):\n            doc.add_paragraph()\n    _para(doc, f\"{meta.get('classification', '')}   \u00b7   {meta.get('docCode', '')}\",\n          size=10, bold=True, color=T.CORAL, after=2)\n    _para(doc, meta.get(\"volume\", \"\"), size=10, bold=True, color=muted_color,\n          after=10)\n    _para(doc, sec.get(\"title\", \"\"), size=34, bold=True, color=title_color,\n          after=4)\n    if sec.get(\"subtitle\"):\n        _para(doc, sec[\"subtitle\"], size=16, color=muted_color, after=10)\n    if fullbleed:\n        _cover_stats_white(doc, sec.get(\"stats\"))\n    else:\n        _stat_tiles(doc, sec.get(\"stats\"))\n    doc.add_page_break()\n\n\ndef _part_divider(doc, sec, lead_break=True):\n    # Sem quebra de entrada quando vem logo ap\u00f3s a capa (que j\u00e1 quebrou) \u2014 evita a\n    # p\u00e1gina em branco entre a capa e a 1\u00aa PARTE. Divisores no meio do documento\n    # mant\u00eam a quebra (come\u00e7am em p\u00e1gina nova).\n    if lead_break:\n        doc.add_page_break()\n    for _ in range(3):\n        doc.add_paragraph()\n    _para(doc, sec.get(\"part\", \"\"), size=13, bold=True, color=T.CORAL, after=2)\n    _outline_title(doc, sec.get(\"title\", \"\"), 30, T.INK, level=1, after=4)\n    if sec.get(\"subtitle\"):\n        _para(doc, sec[\"subtitle\"], size=15, color=T.MUTED)\n\n\ndef _stat_band(doc, sec):\n    if sec.get(\"headline\"):\n        _para(doc, _clip(sec[\"headline\"], 200), size=20, bold=True, color=T.INK,\n              after=8)\n    _stat_tiles(doc, sec.get(\"stats\"))\n    if sec.get(\"body\"):\n        _body(doc, sec[\"body\"], size=11, color=T.INK, after=6)\n\n\ndef _attack_chain(doc, sec):\n    _heading(doc, \"Cadeia de Ataque\", 1)\n    for lane in (sec.get(\"lanes\") or [])[:6]:\n        _para(doc, _clip(lane.get(\"title\", \"\"), 120), size=12, bold=True,\n              color=T.INK, after=2)\n        steps = (lane.get(\"steps\") or [])[:6]\n        if steps:\n            _para(doc, \"  \u2192  \".join(_clip(s.get(\"label\", \"\"), 24) for s in steps),\n                  size=11, bold=True, color=T.PRIMARY, after=2)\n        for s in steps:\n            if s.get(\"detail\"):\n                p = doc.add_paragraph(style=\"List Bullet\")\n                _run(p, f\"{_clip(s.get('label',''),24)}: {_clip(s['detail'],120)}\",\n                     size=10, color=T.MUTED)\n        doc.add_paragraph()\n\n\ndef _roadmap(doc, sec):\n    _heading(doc, \"Plano de Remedia\u00e7\u00e3o por Fase\", 1)\n    phases = (sec.get(\"phases\") or [])[:4]\n    t = doc.add_table(rows=1, cols=3)\n    t.style = \"Table Grid\"\n    for j, hd in enumerate([\"Janela\", \"Foco\", \"A\u00e7\u00f5es\"]):\n        c = t.cell(0, j)\n        c.text = \"\"\n        _shade(c, T.PRIMARY)\n        _run(c.paragraphs[0], hd, size=10, bold=True, color=\"FFFFFF\")\n    for ph in phases:\n        row = t.add_row()\n        _run(row.cells[0].paragraphs[0], ph.get(\"window\", \"\"), size=10,\n             bold=True, color=T.INK)\n        _run(row.cells[1].paragraphs[0], ph.get(\"label\", \"\"), size=10,\n             color=T.MUTED)\n        acts = ph.get(\"actions\") or []\n        cell = row.cells[2]\n        cell.text = \"\"\n        for k, a in enumerate(acts[:6]):\n            p = cell.paragraphs[0] if k == 0 else cell.add_paragraph()\n            _run(p, \"\u25b8 \" + _clip(a, 90), size=9, color=T.INK)\n    doc.add_paragraph()\n\n\ndef _cost_incident(doc, sec):\n    _heading(doc, \"Custo da Remedia\u00e7\u00e3o \u00d7 Custo do Incidente\", 1)\n    t = doc.add_table(rows=2, cols=2)\n    t.style = \"Table Grid\"\n    h0 = t.cell(0, 0)\n    h0.text = \"\"\n    _shade(h0, T.SUCCESS)\n    _run(h0.paragraphs[0], \"REMEDIA\u00c7\u00c3O \u2014 INVESTIMENTO\", size=10, bold=True,\n         color=\"FFFFFF\")\n    h1 = t.cell(0, 1)\n    h1.text = \"\"\n    _shade(h1, T.DESTRUCTIVE)\n    _run(h1.paragraphs[0], \"INCIDENTE N\u00c3O REMEDIADO \u2014 RISCO\", size=10, bold=True,\n         color=\"FFFFFF\")\n    cr = t.cell(1, 0)\n    cr.text = \"\"\n    for k, r in enumerate((sec.get(\"remediation\") or [])[:6]):\n        p = cr.paragraphs[0] if k == 0 else cr.add_paragraph()\n        _run(p, \"\u25c6 \" + _clip(r, 90), size=10, color=T.INK)\n    ci = t.cell(1, 1)\n    ci.text = \"\"\n    inc = (sec.get(\"incident\") or [])[:4]\n    for k, it in enumerate(inc):\n        p = ci.paragraphs[0] if k == 0 else ci.add_paragraph()\n        _run(p, \"\u25c6 \" + _clip(it.get(\"label\", \"\"), 60), size=10, bold=True,\n             color=T.DESTRUCTIVE)\n        if it.get(\"detail\"):\n            pp = ci.add_paragraph()\n            _run(pp, \"   \" + _clip(it[\"detail\"], 90), size=9, color=T.MUTED)\n    doc.add_paragraph()\n\n\ndef _partner_value(doc, sec):\n    _heading(doc, _clip(sec.get(\"title\", \"Parceria\"), 80), 1)\n    for p in (sec.get(\"points\") or [])[:6]:\n        _para(doc, _clip(p.get(\"title\", \"\"), 60), size=13, bold=True,\n              color=T.PRIMARY, after=1)\n        _para(doc, _clip(p.get(\"body\", \"\"), 400), size=11, color=T.INK, after=6)\n\n\ndef _next_steps(doc, sec):\n    _heading(doc, \"Pr\u00f3ximos Passos\", 1)\n    for i, s in enumerate((sec.get(\"steps\") or [])[:6], 1):\n        _para(doc, f\"{i}.  {_clip(s, 200)}\", size=12, color=T.INK, after=4)\n    brand = sec.get(\"_brand\") or {}\n    contact = \" \u00b7 \".join(\n        [x for x in [brand.get(\"name\", \"\"), brand.get(\"contact\", \"\"),\n                     brand.get(\"tagline\", \"\")] if x])\n    if contact:\n        _para(doc, contact, size=10, color=T.MUTED, after=2)\n\n\ndef _kpis(doc, kpis):\n    tiles = [\n        (\"Total de achados\", str(kpis.get(\"total\", 0))),\n        (\"Risco (0-100)\", str(kpis.get(\"riskScore\", 0))),\n        (\"CVSS m\u00e9dio\", str(kpis.get(\"avgCvss\") if kpis.get(\"avgCvss\") is not None else \"-\")),\n        (\"Cr\u00edticos+Altos\", str(kpis.get(\"bySeverity\", {}).get(\"critical\", 0)\n                               + kpis.get(\"bySeverity\", {}).get(\"high\", 0))),\n    ]\n    t = doc.add_table(rows=2, cols=4)\n    t.alignment = WD_TABLE_ALIGNMENT.CENTER\n    for j, (label, val) in enumerate(tiles):\n        c0 = t.cell(0, j)\n        c0.text = \"\"\n        _shade(c0, T.SURFACE_ALT)\n        _run(c0.paragraphs[0], label.upper(), size=9, bold=True, color=T.MUTED)\n        c1 = t.cell(1, j)\n        c1.text = \"\"\n        _shade(c1, T.SURFACE_ALT)\n        _run(c1.paragraphs[0], val, size=26, bold=True, color=T.PRIMARY,\n             font=T.FONT_DISPLAY)\n    doc.add_paragraph()\n\n\ndef _severity_chart(doc, data):\n    # Barras horizontais de verdade: c\u00e9lula sombreada com a cor da severidade e\n    # largura proporcional \u00e0 contagem (antes era \"\u2588\u2588\u2588\u2588\" em texto). A c\u00e9lula\n    # restante fica sem borda/preenchimento (invis\u00edvel) \u2014 s\u00f3 a barra aparece.\n    dist = data.get(\"severityDistribution\", [])\n    maxc = max([d.get(\"count\", 0) for d in dist] + [1])\n    TRACK = 5.6  # polegadas da trilha total da barra\n    for d in dist:\n        sev = d.get(\"severity\")\n        c = d.get(\"count\", 0)\n        color = T.SEVERITY_COLOR.get(sev, T.MUTED)\n        lbl = doc.add_paragraph()\n        lbl.paragraph_format.space_before = Pt(4)\n        lbl.paragraph_format.space_after = Pt(1)\n        _run(lbl, f\"{T.SEVERITY_LABEL.get(sev, sev)}  \u00b7  {c}\", size=10,\n             bold=True, color=color)\n        frac = (c / maxc) if maxc else 0.0\n        barw = max(0.06, TRACK * frac)\n        t = doc.add_table(rows=1, cols=2)\n        t.allow_autofit = False\n        bar, rest = t.cell(0, 0), t.cell(0, 1)\n        bar.width = Inches(barw)\n        rest.width = Inches(max(0.02, TRACK - barw))\n        _shade(bar, color)\n        for cell in (bar, rest):\n            pc = cell.paragraphs[0]\n            pc.paragraph_format.space_before = Pt(0)\n            pc.paragraph_format.space_after = Pt(0)\n            r = pc.add_run(\" \")\n            r.font.size = Pt(7)\n    doc.add_paragraph()\n\n\ndef _risk_matrix(doc, data):\n    cells = {(c[\"likelihood\"], c[\"impact\"]): c.get(\"count\", 0)\n             for c in data.get(\"riskMatrix\", [])}\n\n    def band(score):\n        if score >= 8:\n            return T.DESTRUCTIVE\n        if score >= 5:\n            return T.WARNING\n        if score >= 3:\n            return \"6F9BF5\"\n        return T.SUCCESS\n    t = doc.add_table(rows=5, cols=5)\n    t.alignment = WD_TABLE_ALIGNMENT.CENTER\n    for r in range(5):\n        li = 5 - r\n        for col in range(5):\n            im = col + 1\n            cell = t.cell(r, col)\n            cell.text = \"\"\n            _shade(cell, band(li + im))\n            cnt = cells.get((li, im), 0)\n            _run(cell.paragraphs[0], str(cnt) if cnt else \"\", size=12,\n                 bold=True, color=\"FFFFFF\")\n            cell.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER\n    doc.add_paragraph()\n\n\ndef _finding_card(doc, sec):\n    f = sec[\"finding\"]\n    sev = f.get(\"severity\", \"info\")\n    p = doc.add_paragraph()\n    # T\u00edtulo do achado como Heading 2 \u2192 aparece no outline/TOC do Word.\n    try:\n        p.style = doc.styles[\"Heading 2\"]\n    except KeyError:\n        pass\n    p.paragraph_format.space_before = Pt(10)\n    _run(p, f\"[{T.SEVERITY_LABEL.get(sev, sev).upper()}] \", size=13, bold=True,\n         color=T.SEVERITY_COLOR.get(sev, T.MUTED))\n    _run(p, f\"{f.get('ref','')} \u00b7 {_clip(f.get('title',''),90)}\", size=13,\n         bold=True, color=T.INK)\n    meta = []\n    if f.get(\"affectedAsset\"):\n        meta.append(f\"Ativo: {f['affectedAsset']}\")\n    if f.get(\"weaknessClass\"):\n        meta.append(f\"Classe: {f['weaknessClass']}\")\n    if f.get(\"cvssVector\"):\n        meta.append(f\"CVSS: {f['cvssVector']}\")\n    if f.get(\"cwe\"):\n        meta.append(f\"CWE: {f['cwe']}\")\n    if meta:\n        _para(doc, \"   \".join(meta), size=10, color=T.MUTED, after=4)\n    if f.get(\"narrative\"):\n        _para(doc, \"NARRATIVA:\", size=10, bold=True, color=T.PRIMARY, after=1)\n        _body(doc, f[\"narrative\"], size=10, color=T.INK, after=4)\n    for label, key in [(\"Descri\u00e7\u00e3o\", \"description\"), (\"Impacto\", \"impact\"),\n                       (\"Remedia\u00e7\u00e3o\", \"remediation\")]:\n        if f.get(key):\n            _para(doc, label.upper() + \":\", size=10, bold=True,\n                  color=T.PRIMARY, after=1)\n            _body(doc, f[key], size=11, color=T.INK, after=6)\n    if sec.get(\"showPoc\") and f.get(\"reproductionSteps\"):\n        _para(doc, \"REPRODU\u00c7\u00c3O:\", size=10, bold=True, color=T.PRIMARY, after=2)\n        for i, s in enumerate(f[\"reproductionSteps\"], 1):\n            _body(doc, f\"{i}. {s}\", size=10, color=T.INK, after=1)\n    if sec.get(\"showPoc\"):\n        _evidence_docx(doc, f)\n\n\ndef _embed_image_docx(doc, path, caption=None):\n    if not path or not os.path.exists(path):\n        return False\n    try:\n        doc.add_picture(path, width=Inches(6.0))\n        doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER\n    except Exception:\n        return False\n    cap = \"\u25b2 \" + _clip(caption, 160) if caption else \"\u25b2 Evid\u00eancia visual capturada\"\n    _para(doc, cap, size=8, color=T.MUTED, after=8,\n          align=WD_ALIGN_PARAGRAPH.CENTER)\n    return True\n\n\ndef _placeholder_docx(doc, text):\n    \"\"\"Aviso vis\u00edvel de evid\u00eancia ausente \u2014 nunca pular em sil\u00eancio (WS3).\"\"\"\n    t = doc.add_table(rows=1, cols=1)\n    cell = t.cell(0, 0)\n    cell.text = \"\"\n    _shade(cell, T.SURFACE_ALT)\n    _run(cell.paragraphs[0], text, size=10, bold=True, color=T.WARNING)\n    doc.add_paragraph()\n\n\ndef _ev_sorted(f):\n    ev = f.get(\"evidence\") or []\n    return sorted(\n        ev,\n        key=lambda e: e.get(\"stepIndex\") if e.get(\"stepIndex\") is not None else 1_000_000,\n    )\n\n\ndef _evidence_block(doc, steps):\n    \"\"\"Cadeia de evid\u00eancia estilo TERMINAL (modelo-ouro SYN): uma c\u00e9lula de fundo\n    navy escuro com o texto MONO colorido \u2014 cabe\u00e7alho do passo cinza, comando\n    ciano, output neutro, prova verde. Um bloco por achado (toda a cadeia junta).\"\"\"\n    t = doc.add_table(rows=1, cols=1)\n    cell = t.cell(0, 0)\n    cell.text = \"\"\n    _shade(cell, T.EV_BG)\n    state = {\"first\": True}\n\n    def line(before=0):\n        p = cell.paragraphs[0] if state[\"first\"] else cell.add_paragraph()\n        state[\"first\"] = False\n        p.paragraph_format.space_before = Pt(before)\n        p.paragraph_format.space_after = Pt(0)\n        return p\n\n    def mono(p, text, color, bold=False):\n        r = p.add_run()\n        r.font.size = Pt(8.5)\n        r.font.bold = bold\n        _set_font(r, T.FONT_MONO)\n        r.font.color.rgb = _rgb(color)\n        for i, ln in enumerate(str(text).split(\"\\n\")):\n            if i:\n                r.add_break()\n            r.add_text(ln)\n\n    for idx, (n, e) in enumerate(steps):\n        ph = line(before=(2 if idx == 0 else 8))\n        head = f\"{n}.\"\n        if e.get(\"toolName\"):\n            head += f\" [{e['toolName']}]\"\n        mono(ph, head, T.EV_META, bold=True)\n        lbl = e.get(\"label\")\n        if lbl and lbl != e.get(\"toolName\"):\n            mono(ph, \"  \" + _clip(lbl, 160), T.EV_META)\n        if e.get(\"command\"):\n            pc = line()\n            mono(pc, \"$ \", T.EV_OK, bold=True)\n            mono(pc, str(e[\"command\"]), T.EV_CMD)\n        if e.get(\"snippet\"):\n            mono(line(), e[\"snippet\"], T.EV_OUT)\n        if e.get(\"resultSummary\"):\n            pr = line()\n            mono(pr, \"\u2192 prova: \", T.EV_OK, bold=True)\n            mono(pr, e[\"resultSummary\"], T.EV_OUT)\n    doc.add_paragraph()\n\n\ndef _evidence_docx(doc, f):\n    ev = _ev_sorted(f)\n    steps = [(e.get(\"stepIndex\") or i, e) for i, e in enumerate(ev, 1)]\n    text_steps = [\n        (n, e) for (n, e) in steps\n        if e.get(\"command\") or e.get(\"snippet\") or e.get(\"resultSummary\")\n    ]\n    img_steps = [e for (n, e) in steps if e.get(\"imagePath\")]\n    if text_steps:\n        _para(doc, \"CADEIA DE EVID\u00caNCIA\", size=9, bold=True, color=T.PRIMARY,\n              after=3)\n        _evidence_block(doc, text_steps)\n    img_rendered = 0\n    for e in img_steps:\n        if _embed_image_docx(doc, e.get(\"imagePath\"), e.get(\"label\")):\n            img_rendered += 1\n        else:\n            _placeholder_docx(\n                doc, \"\u26a0 Evid\u00eancia visual referenciada n\u00e3o dispon\u00edvel no pacote.\")\n    if img_rendered == 0 and f.get(\"severity\") in (\"critical\", \"high\"):\n        if any(e.get(\"imageUnavailable\") for (n, e) in steps):\n            _placeholder_docx(\n                doc, \"\u26a0 Evid\u00eancia visual capturada, por\u00e9m indispon\u00edvel (expirada/removida do armazenamento).\")\n        else:\n            _placeholder_docx(\n                doc, \"\u26a0 Evid\u00eancia visual n\u00e3o capturada para este achado.\")\n\n\ndef _fixed_table(doc, headers, widths):\n    \"\"\"Tabela de layout FIXO (n\u00e3o deixa o autofit esmagar colunas), cabe\u00e7alho\n    navy que REPETE em cada p\u00e1gina, larguras por coluna (polegadas).\"\"\"\n    t = doc.add_table(rows=1, cols=len(headers))\n    t.alignment = WD_TABLE_ALIGNMENT.CENTER\n    t.autofit = False\n    t.allow_autofit = False\n    lay = OxmlElement(\"w:tblLayout\")\n    lay.set(qn(\"w:type\"), \"fixed\")\n    t._tbl.tblPr.append(lay)\n    hr = t.rows[0]\n    th = OxmlElement(\"w:tblHeader\")  # repete o cabe\u00e7alho a cada p\u00e1gina\n    th.set(qn(\"w:val\"), \"true\")\n    hr._tr.get_or_add_trPr().append(th)\n    for j, hd in enumerate(headers):\n        c = t.cell(0, j)\n        c.text = \"\"\n        c.width = Inches(widths[j])\n        _shade(c, T.PRIMARY)\n        p = c.paragraphs[0]\n        p.paragraph_format.space_before = Pt(2)\n        p.paragraph_format.space_after = Pt(2)\n        _run(p, hd, size=9, bold=True, color=\"FFFFFF\")\n    return t\n\n\ndef _table(doc, findings, remediation=False):\n    if remediation:\n        headers = [\"Ref\", \"Sev\", \"Ativo\", \"Remedia\u00e7\u00e3o\"]\n        widths = [0.75, 0.85, 1.95, 3.35]\n        clips = [None, None, 70, 240]\n    else:\n        headers = [\"Ref\", \"Sev\", \"T\u00edtulo\", \"Ativo\", \"CVSS\"]\n        widths = [0.75, 0.85, 3.05, 1.75, 0.55]\n        clips = [None, None, 130, 58, None]\n    t = _fixed_table(doc, headers, widths)\n    for idx, f in enumerate(findings):\n        sev = f.get(\"severity\", \"info\")\n        row = t.add_row()\n        fill = T.SURFACE_ALT if idx % 2 == 0 else T.SURFACE  # zebra\n        cvss = f.get(\"cvssScore\")\n        cvss_s = f\"{cvss:.1f}\" if isinstance(cvss, (int, float)) else \"\u2014\"\n        raw = ([f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                f.get(\"affectedAsset\", \"\"), f.get(\"remediation\", \"\")]\n               if remediation else\n               [f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                f.get(\"title\", \"\"), f.get(\"affectedAsset\", \"\"), cvss_s])\n        for j, v in enumerate(raw):\n            cell = row.cells[j]\n            cell.text = \"\"\n            cell.width = Inches(widths[j])\n            _shade(cell, fill)\n            val = _clip(v, clips[j]) if clips[j] else v\n            p = cell.paragraphs[0]\n            p.paragraph_format.space_before = Pt(1)\n            p.paragraph_format.space_after = Pt(1)\n            _run(p, val, size=9, bold=(j == 1),\n                 color=(T.SEVERITY_COLOR.get(sev, T.INK) if j == 1 else T.INK))\n    doc.add_paragraph()\n\n\ndef _callout(doc, sec):\n    col = T.CALLOUT_COLOR.get(sec.get(\"tone\", \"info\"), T.PRIMARY)\n    t = doc.add_table(rows=1, cols=1)\n    cell = t.cell(0, 0)\n    cell.text = \"\"\n    _shade(cell, T.SURFACE_ALT)\n    _run(cell.paragraphs[0], _clip(sec.get(\"text\", \"\"), 2000), size=12, bold=True,\n         color=col)\n    doc.add_paragraph()\n\n\ndef _outline_title(doc, text, size, color, level=1, after=4, before=0):\n    \"\"\"T\u00edtulo com estilo Heading NOMEADO (entra no SUM\u00c1RIO/outline do Word) mas\n    com a apar\u00eancia da marca via run \u2014 sem a borda do _heading.\"\"\"\n    p = doc.add_paragraph()\n    try:\n        p.style = doc.styles[\"Heading 1\" if level == 1 else \"Heading 2\"]\n    except KeyError:\n        pass\n    p.paragraph_format.space_before = Pt(before)\n    p.paragraph_format.space_after = Pt(after)\n    _run(p, text, size=size, bold=True, color=color, font=T.FONT_DISPLAY)\n    return p\n\n\ndef _toc(doc, entries):\n    \"\"\"SUM\u00c1RIO \u00e0 prova de falha: campo TOC (Heading 1) marcado `dirty` \u2192 o Word\n    popula as p\u00e1ginas ao atualizar. O RESULTADO do campo j\u00e1 traz a LISTA EST\u00c1TICA\n    das se\u00e7\u00f5es, ent\u00e3o, atualizando ou n\u00e3o, NUNCA fica vazio/placeholder (vira o\n    sum\u00e1rio paginado OU a lista de se\u00e7\u00f5es limpa).\"\"\"\n    _para(doc, \"SUM\u00c1RIO\", size=20, bold=True, color=T.INK, after=10)\n\n    def _fldchar(p, ftype, dirty=False):\n        r = p.add_run()\n        fc = OxmlElement(\"w:fldChar\")\n        fc.set(qn(\"w:fldCharType\"), ftype)\n        if dirty:\n            fc.set(qn(\"w:dirty\"), \"true\")\n        r._r.append(fc)\n\n    p0 = doc.add_paragraph()\n    _fldchar(p0, \"begin\", dirty=True)\n    r = p0.add_run()\n    it = OxmlElement(\"w:instrText\")\n    it.set(qn(\"xml:space\"), \"preserve\")\n    it.text = ' TOC \\\\o \"1-1\" \\\\h \\\\z \\\\u '\n    r._r.append(it)\n    _fldchar(p0, \"separate\")\n    items = [e for e in (entries or []) if e and e[0]]\n    if not items:\n        _fldchar(p0, \"end\")\n        doc.add_page_break()\n        return\n    for i, (title, level) in enumerate(items):\n        pe = doc.add_paragraph()\n        pe.paragraph_format.space_after = Pt(5)\n        if level:\n            pe.paragraph_format.left_indent = Inches(0.28 * level)  # recuo hier\u00e1rquico\n        _run(pe, title, size=(12 if level == 0 else 11),\n             bold=(level == 0), color=T.INK)\n        if i == len(items) - 1:\n            _fldchar(pe, \"end\")  # fecha o campo na \u00faltima entrada\n    doc.add_page_break()\n\n\ndef render_docx(model, out_path):\n    doc = Document()\n    meta = model.get(\"meta\", {})\n    _apply_brand(meta)\n    style = doc.styles[\"Normal\"]\n    style.font.name = T.FONT_BODY\n    style.font.size = Pt(11)\n    _setup_footer(doc, meta)\n    brand = meta.get(\"brand\", {})\n    # SUM\u00c1RIO completo: partes (n\u00edvel 0) + headings de se\u00e7\u00e3o (n\u00edvel 1) + as\n    # sub-se\u00e7\u00f5es/fases da narrativa (n\u00edvel 2). T\u00edtulos de achado s\u00e3o findingCard\n    # (n\u00e3o \"heading\"), ent\u00e3o N\u00c3O entram \u2014 o sum\u00e1rio n\u00e3o incha com os N achados.\n    toc_entries = []\n    for s in model.get(\"sections\", []):\n        st = s.get(\"type\")\n        if st == \"partDivider\":\n            toc_entries.append((s.get(\"title\", \"\"), 0))\n        elif st == \"heading\":\n            lvl = s.get(\"level\", 1)\n            if lvl in (1, 2):\n                toc_entries.append((s.get(\"text\", \"\"), lvl))\n    prev_type = None\n    for sec in model.get(\"sections\", []):\n        t = sec.get(\"type\")\n        if t == \"cover\":\n            _cover(doc, sec, meta)\n            _toc(doc, toc_entries)\n        elif t == \"partDivider\":\n            _part_divider(doc, sec, lead_break=(prev_type != \"cover\"))\n        elif t == \"divider\":\n            doc.add_page_break()\n        elif t == \"heading\":\n            _heading(doc, sec.get(\"text\", \"\"), sec.get(\"level\", 1))\n        elif t == \"paragraph\":\n            _body(doc, sec.get(\"text\", \"\"), size=11, color=T.INK)\n        elif t == \"bullets\":\n            for it in sec.get(\"items\", []):\n                p = doc.add_paragraph(style=\"List Bullet\")\n                _run(p, str(it), size=11, color=T.INK)\n        elif t == \"statBand\":\n            _stat_band(doc, sec)\n        elif t == \"kpis\":\n            _kpis(doc, sec.get(\"kpis\", {}))\n        elif t == \"severityChart\":\n            _severity_chart(doc, sec.get(\"data\", {}))\n        elif t == \"riskMatrix\":\n            _risk_matrix(doc, sec.get(\"data\", {}))\n        elif t == \"attackChain\":\n            _attack_chain(doc, sec)\n        elif t == \"findingCard\":\n            _finding_card(doc, sec)\n        elif t == \"findingsTable\":\n            _table(doc, sec.get(\"findings\", []))\n        elif t == \"remediationMatrix\":\n            _table(doc, sec.get(\"findings\", []), remediation=True)\n        elif t == \"roadmap\":\n            _roadmap(doc, sec)\n        elif t == \"costVsIncident\":\n            _cost_incident(doc, sec)\n        elif t == \"partnerValue\":\n            _partner_value(doc, sec)\n        elif t == \"nextSteps\":\n            sec[\"_brand\"] = brand\n            _next_steps(doc, sec)\n        elif t == \"callout\":\n            _callout(doc, sec)\n        prev_type = t\n    doc.save(out_path)\n    # Embute IBM Plex no pacote OOXML (best-effort: falha \u2192 DOCX v\u00e1lido s\u00f3 com o\n    # nome da fonte). Sem isso o Word do cliente cai p/ serifa de substitui\u00e7\u00e3o.\n    try:\n        import fontembed\n        fontembed.embed_fonts(out_path)\n    except Exception:\n        pass\n",
  "fontembed.py": "\"\"\"Embute as fontes IBM Plex (TrueType) no pacote OOXML do DOCX \u2014 formato\n\"obfuscated font\" (.odttf) do ECMA-376 \u2014 para o Word do cliente renderizar a\ntipografia da marca MESMO sem a fonte instalada. Sem isso, Word/LibreOffice\ncaem para uma serifa de substitui\u00e7\u00e3o (o relat\u00f3rio sai com cara de papel\nacad\u00eamico, n\u00e3o de consultoria).\n\nChamado por docx_renderer.render_docx() ao final, de forma DEFENSIVA: qualquer\nfalha deixa o DOCX v\u00e1lido (s\u00f3 sem embed \u2192 nome da fonte) \u2014 nunca quebra a\ngera\u00e7\u00e3o. Os .ttf v\u00eam de fonts/ (o job do trigger os escreve no sandbox E2B via\nRENDERER_FONTS; em teste local ficam ao lado dos .py). Validado: o soffice usa\nas fontes embutidas (IBM Plex aparece subsetada no PDF).\"\"\"\n\nimport os\nimport re\nimport uuid\nimport zipfile\n\nimport theme as T\n\n# (fam\u00edlia OOXML, variante theme) \u2014 s\u00f3 as presentes s\u00e3o embutidas.\n_EMBED = [\n    (\"IBM Plex Sans\", \"normal\", \"embedRegular\"),\n    (\"IBM Plex Sans\", \"bold\", \"embedBold\"),\n    (\"IBM Plex Mono\", \"normal\", \"embedRegular\"),\n]\n_REL_FONT = (\"http://schemas.openxmlformats.org/officeDocument/2006/\"\n             \"relationships/font\")\n_CT_ODTTF = \"application/vnd.openxmlformats-officedocument.obfuscatedFont\"\n\n\ndef _obfuscate(data, guid_hex):\n    \"\"\"XOR dos 32 primeiros bytes com os 16 bytes do GUID invertidos (ECMA-376).\n    \u00c9 a sua pr\u00f3pria inversa (o Word desofusca com o mesmo XOR).\"\"\"\n    key = bytes.fromhex(guid_hex)[::-1]\n    b = bytearray(data)\n    for i in range(32):\n        b[i] ^= key[i % 16]\n    return bytes(b)\n\n\ndef embed_fonts(docx_path):\n    \"\"\"Embute IBM Plex no .docx in-place. Defensivo: no-op se n\u00e3o houver .ttf;\n    reescreve o zip atomicamente (nunca deixa o arquivo corrompido).\"\"\"\n    # agrupa variantes presentes por fam\u00edlia\n    byfam = {}\n    for family, variant, tag in _EMBED:\n        path = T.font_path(family, variant)\n        if path and os.path.exists(path):\n            byfam.setdefault(family, []).append((tag, path))\n    if not byfam:\n        return False\n\n    with zipfile.ZipFile(docx_path) as z:\n        files = {n: z.read(n) for n in z.namelist()}\n    if \"word/fontTable.xml\" not in files or \"word/settings.xml\" not in files:\n        return False\n\n    odttf, rels, fontxml, ridn = {}, [], [], 100\n    for family, variants in byfam.items():\n        embeds = []\n        for tag, path in variants:\n            with open(path, \"rb\") as fh:\n                data = fh.read()\n            guid = uuid.uuid4()\n            ridn += 1\n            rid, fname = f\"rIdFe{ridn}\", f\"fontFe{ridn}.odttf\"\n            odttf[\"word/fonts/\" + fname] = _obfuscate(data, guid.hex)\n            rels.append((rid, fname))\n            embeds.append(\n                f'<w:{tag} r:id=\"{rid}\" '\n                f'w:fontKey=\"{{{str(guid).upper()}}}\" w:subsetted=\"0\"/>')\n        fontxml.append(f'<w:font w:name=\"{family}\">{\"\".join(embeds)}</w:font>')\n\n    ft = files[\"word/fontTable.xml\"].decode(\"utf-8\")\n    if \"</w:fonts>\" not in ft:\n        return False\n    files[\"word/fontTable.xml\"] = ft.replace(\n        \"</w:fonts>\", \"\".join(fontxml) + \"</w:fonts>\").encode(\"utf-8\")\n\n    relpath = \"word/_rels/fontTable.xml.rels\"\n    rx = files.get(relpath, (\n        '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>'\n        '<Relationships xmlns=\"http://schemas.openxmlformats.org/'\n        'package/2006/relationships\"></Relationships>').encode()).decode(\"utf-8\")\n    entries = \"\".join(\n        f'<Relationship Id=\"{rid}\" Type=\"{_REL_FONT}\" Target=\"fonts/{fn}\"/>'\n        for rid, fn in rels)\n    files[relpath] = rx.replace(\n        \"</Relationships>\", entries + \"</Relationships>\").encode(\"utf-8\")\n\n    ct = files[\"[Content_Types].xml\"].decode(\"utf-8\")\n    if \"obfuscatedFont\" not in ct:\n        ct = ct.replace(\n            \"</Types>\",\n            f'<Default Extension=\"odttf\" ContentType=\"{_CT_ODTTF}\"/></Types>')\n    files[\"[Content_Types].xml\"] = ct.encode(\"utf-8\")\n\n    st = files[\"word/settings.xml\"].decode(\"utf-8\")\n    if \"embedTrueTypeFonts\" not in st:\n        st = re.sub(r\"(<w:settings\\b[^>]*>)\", r\"\\1<w:embedTrueTypeFonts/>\",\n                    st, count=1)\n    files[\"word/settings.xml\"] = st.encode(\"utf-8\")\n\n    files.update(odttf)\n    tmp = docx_path + \".fe.tmp\"\n    with zipfile.ZipFile(tmp, \"w\", zipfile.ZIP_DEFLATED) as z:\n        for n, d in files.items():\n            z.writestr(n, d)\n    os.replace(tmp, docx_path)\n    return True\n",
  "logo.py": "\"\"\"Logo OFICIAL Suricatoos p/ a capa dos relatorios.\n\nRasterizado dos SVGs oficiais (iCloud: \"Suricatoos 2.svg\" dark / \"Suricatoos.svg\"\nlight) via rsvg-convert (1600px, transparente). LOGO_BLUE = fundo claro (wordmark\nazul + suricata coral); LOGO_WHITE = capa/fundo escuro (wordmark branco + suricata\nazul). write_logo(dark=True) -> branco; dark=False -> azul.\n\"\"\"\nimport base64 as _b64\nimport os as _os\nimport tempfile as _tmp\n\nLOGO_BLUE = \"\"\n\nLOGO_WHITE = \"\"\n\n\ndef write_logo(dark=False):\n    data = LOGO_WHITE if dark else LOGO_BLUE\n    raw = _b64.b64decode(data)\n    out = _os.path.join(\n        _tmp.gettempdir(), \"suricatoos_logo_%s.png\" % (\"w\" if dark else \"b\"))\n    with open(out, \"wb\") as fh:\n        fh.write(raw)\n    return out\n",
  "pdf_renderer.py": "\"\"\"Renderer PDF (reportlab Platypus) do ReportModel \u2014 estilo \"dossie\".\n\nCasca de dossie: capa com codigo de documento + faixa de KPIs, rodape (canvas)\ncom classificacao + docCode + numero de pagina, divisorias de PARTE. Marca\nconfiguravel por MSSP (aplicada ANTES de montar os estilos). Vetorial, sem\nchromium.\"\"\"\n\nfrom reportlab.lib.pagesizes import A4\nfrom reportlab.lib.units import mm\nfrom reportlab.lib import colors\nfrom reportlab.lib.enums import TA_LEFT, TA_CENTER\nfrom reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle\nfrom reportlab.platypus import (\n    SimpleDocTemplate,\n    BaseDocTemplate,\n    PageTemplate,\n    Frame,\n    Paragraph,\n    Spacer,\n    Table,\n    TableStyle,\n    PageBreak,\n    HRFlowable,\n    Image,\n)\nfrom reportlab.platypus.tableofcontents import TableOfContents\nfrom reportlab.lib.utils import ImageReader\nimport os\n\nimport theme as T\nimport logo\n\n\n_FONTS_READY = False\nFONT_SANS = \"Helvetica\"\nFONT_SANS_BOLD = \"Helvetica-Bold\"\nFONT_MONO = \"Courier\"\n\n\ndef _register_fonts():\n    \"\"\"Registra IBM Plex (reportlab EMBUTE os glifos no PDF). Idempotente;\n    mantem o fallback Helvetica/Courier se os .ttf nao estiverem presentes.\"\"\"\n    global _FONTS_READY, FONT_SANS, FONT_SANS_BOLD, FONT_MONO\n    if _FONTS_READY:\n        return\n    _FONTS_READY = True\n    try:\n        from reportlab.pdfbase import pdfmetrics\n        from reportlab.pdfbase.ttfonts import TTFont\n\n        reg = T.font_path(\"IBM Plex Sans\", \"normal\")\n        bold = T.font_path(\"IBM Plex Sans\", \"bold\")\n        mono = T.font_path(\"IBM Plex Mono\", \"normal\")\n        if reg and bold and mono:\n            pdfmetrics.registerFont(TTFont(\"IBMPlexSans\", reg))\n            pdfmetrics.registerFont(TTFont(\"IBMPlexSans-Bold\", bold))\n            pdfmetrics.registerFont(TTFont(\"IBMPlexMono\", mono))\n            pdfmetrics.registerFontFamily(\n                \"IBMPlexSans\", normal=\"IBMPlexSans\",\n                bold=\"IBMPlexSans-Bold\", italic=\"IBMPlexSans\",\n                boldItalic=\"IBMPlexSans-Bold\")\n            # Fonte-base padrao do canvas (senao o reportlab emite um bloco\n            # BT/ET vazio de init com /Helvetica em cada pagina \u2014 inofensivo,\n            # mas deixaria \"Helvetica\" no PDF).\n            from reportlab import rl_config\n\n            rl_config.canvas_basefontname = \"IBMPlexSans\"\n            FONT_SANS = \"IBMPlexSans\"\n            FONT_SANS_BOLD = \"IBMPlexSans-Bold\"\n            FONT_MONO = \"IBMPlexMono\"\n    except Exception:\n        pass\n\n\ndef C(h):\n    return colors.HexColor(\"#\" + h)\n\n\ndef _ts(cmds):\n    \"\"\"TableStyle com FONTNAME base em IBM Plex, p/ celulas string nao ca\u00edrem no\n    Helvetica padrao do reportlab. Comandos especificos (ex.: header bold) vem\n    depois e sobrepoem.\"\"\"\n    return TableStyle([(\"FONTNAME\", (0, 0), (-1, -1), FONT_SANS)] + list(cmds))\n\n\ndef _clip(s, n):\n    s = str(s or \"\")\n    return s if len(s) <= n else s[: n - 1] + \"\u2026\"\n\n\ndef _esc(s):\n    return (str(s or \"\").replace(\"&\", \"&amp;\").replace(\"<\", \"&lt;\").replace(\">\", \"&gt;\"))\n\n\ndef _ml(s):\n    \"\"\"Escapa p/ Paragraph do reportlab e preserva quebras de linha. N\u00c3O trunca \u2014\n    o Platypus pagina sozinho (corpo de achado/evid\u00eancia nunca \u00e9 cortado).\"\"\"\n    return _esc(s).replace(\"\\n\", \"<br/>\")\n\n\ndef _apply_brand(meta):\n    brand = meta.get(\"brand\") or {}\n    if brand.get(\"primary\"):\n        T.PRIMARY = brand[\"primary\"]\n    if brand.get(\"accent\"):\n        T.CORAL = brand[\"accent\"]\n    if brand.get(\"wordmark\"):\n        T.WORDMARK = brand[\"wordmark\"]\n\n\ndef _styles():\n    _register_fonts()\n    ss = getSampleStyleSheet()\n    # Estilos base herdados tambem em IBM Plex (evita vazar Helvetica/Times).\n    ss[\"Normal\"].fontName = FONT_SANS\n    ss[\"Title\"].fontName = FONT_SANS_BOLD\n    ss[\"Heading1\"].fontName = FONT_SANS_BOLD\n    ss.add(ParagraphStyle(\"Cover\", parent=ss[\"Title\"], fontName=FONT_SANS_BOLD,\n                          fontSize=30, textColor=C(T.INK), spaceAfter=8, leading=34,\n                          alignment=TA_LEFT))\n    ss.add(ParagraphStyle(\"Wordmark\", parent=ss[\"Normal\"], fontName=FONT_SANS_BOLD,\n                          fontSize=18, textColor=C(T.CORAL)))\n    ss.add(ParagraphStyle(\"H1\", parent=ss[\"Heading1\"], fontName=FONT_SANS_BOLD,\n                          fontSize=15, textColor=C(T.PRIMARY), spaceBefore=12, spaceAfter=4))\n    ss.add(ParagraphStyle(\"Body2\", parent=ss[\"Normal\"], fontName=FONT_SANS,\n                          fontSize=10.5, textColor=C(T.INK), leading=15, spaceAfter=5))\n    ss.add(ParagraphStyle(\"Small\", parent=ss[\"Normal\"], fontName=FONT_SANS,\n                          fontSize=8.5, textColor=C(T.MUTED)))\n    ss.add(ParagraphStyle(\"CardTitle\", parent=ss[\"Normal\"], fontName=FONT_SANS_BOLD,\n                          fontSize=12, textColor=C(T.INK), spaceBefore=8, spaceAfter=2))\n    ss.add(ParagraphStyle(\"KpiVal\", parent=ss[\"Normal\"], fontName=FONT_SANS_BOLD,\n                          fontSize=22, textColor=C(T.PRIMARY), alignment=TA_CENTER))\n    ss.add(ParagraphStyle(\"KpiLabel\", parent=ss[\"Normal\"], fontName=FONT_SANS_BOLD,\n                          fontSize=7.5, textColor=C(T.MUTED), alignment=TA_CENTER))\n    # C\u00f3digo/evid\u00eancia: monoespa\u00e7ada com quebra em qualquer ponto (wordWrap CJK)\n    # p/ n\u00e3o estourar a largura do frame com tokens longos (comandos/sa\u00eddas).\n    ss.add(ParagraphStyle(\"Mono\", parent=ss[\"Normal\"], fontName=FONT_MONO,\n                          fontSize=8, textColor=C(T.MUTED), leading=10,\n                          wordWrap=\"CJK\", spaceAfter=3))\n    return ss\n\n\ndef _band(score):\n    if score >= 8:\n        return T.DESTRUCTIVE\n    if score >= 5:\n        return T.WARNING\n    if score >= 3:\n        return \"6F9BF5\"\n    return T.SUCCESS\n\n\ndef _cover_canvas_factory(meta, cover):\n    def draw(canvas, doc):\n        if doc.page <= 1:\n            # Capa: arte full-bleed da marca (o t\u00edtulo \u00e9 sobreposto por flowables).\n            if cover and os.path.exists(cover):\n                try:\n                    fitted = T.cover_fit(cover, A4[0], A4[1])\n                    canvas.drawImage(fitted, 0, 0, width=A4[0], height=A4[1],\n                                     preserveAspectRatio=False, mask=\"auto\")\n                except Exception:\n                    pass\n            return\n        canvas.saveState()\n        canvas.setFont(FONT_SANS, 7)\n        canvas.setFillColor(C(T.MUTED))\n        canvas.drawString(18 * mm, 8 * mm, _clip(meta.get(\"classification\", \"\"), 80))\n        canvas.drawRightString(A4[0] - 18 * mm, 8 * mm,\n                               f'{meta.get(\"docCode\", \"\")} \u00b7 {doc.page}')\n        canvas.restoreState()\n    return draw\n\n\nclass _TocDocTemplate(BaseDocTemplate):\n    \"\"\"Doc com SUM\u00c1RIO paginado: afterFlowable notifica TOCEntry p/ as partes\n    (estilo 'pdtitle') e os headings de se\u00e7\u00e3o/fase ('TOCH1'/'TOCH2'); multiBuild\n    resolve os n\u00fameros de p\u00e1gina em 2+ passagens. onPage=foot trata capa vs\n    p\u00e1ginas internas (o pr\u00f3prio foot checa doc.page <= 1).\"\"\"\n\n    def __init__(self, filename, foot, **kw):\n        BaseDocTemplate.__init__(self, filename, **kw)\n        fw = self.pagesize[0] - self.leftMargin - self.rightMargin\n        fh = self.pagesize[1] - self.topMargin - self.bottomMargin\n        frame = Frame(self.leftMargin, self.bottomMargin, fw, fh, id=\"normal\")\n        self.addPageTemplates([\n            PageTemplate(id=\"main\", frames=[frame], onPage=foot,\n                         pagesize=self.pagesize),\n        ])\n\n    def afterFlowable(self, flowable):\n        if not isinstance(flowable, Paragraph):\n            return\n        lvl = {\"pdtitle\": 0, \"TOCH1\": 1, \"TOCH2\": 2}.get(\n            getattr(flowable.style, \"name\", \"\"))\n        if lvl is None:\n            return\n        txt = flowable.getPlainText()\n        if txt:\n            self.notify(\"TOCEntry\", (lvl, txt, self.page))\n\n\ndef _summary_block(ss, toc):\n    \"\"\"P\u00e1gina de SUM\u00c1RIO (ap\u00f3s a capa): t\u00edtulo + TOC paginado (preenchido pelo\n    afterFlowable do _TocDocTemplate via multiBuild).\"\"\"\n    return [\n        Paragraph(\"SUM\u00c1RIO\", ParagraphStyle(\"sumh\", parent=ss[\"Cover\"],\n                                             fontSize=22)),\n        Spacer(1, 4 * mm),\n        toc,\n        PageBreak(),\n    ]\n\n\ndef _stat_table(ss, stats):\n    stats = (stats or [])[:4]\n    if not stats:\n        return None\n    lab = [Paragraph(_esc(s.get(\"label\", \"\")).upper(), ss[\"KpiLabel\"]) for s in stats]\n    val = [Paragraph(_esc(s.get(\"value\", \"\")), ss[\"KpiVal\"]) for s in stats]\n    w = (170.0 / len(stats)) * mm\n    tbl = Table([lab, val], colWidths=[w] * len(stats))\n    tbl.setStyle(_ts([\n        (\"BACKGROUND\", (0, 0), (-1, -1), C(T.SURFACE_ALT)),\n        (\"BOX\", (0, 0), (-1, -1), 0.5, C(T.BORDER)),\n        (\"INNERGRID\", (0, 0), (-1, -1), 0.5, C(T.SURFACE)),\n        (\"TOPPADDING\", (0, 0), (-1, -1), 7),\n        (\"BOTTOMPADDING\", (0, 0), (-1, -1), 7),\n    ]))\n    return tbl\n\n\ndef _stat_table_white(ss, stats):\n    \"\"\"KPIs da capa ESCURA (navy/foto): c\u00e9lulas transparentes + texto BRANCO \u2014\n    espelha o _cover_stats_white do DOCX (valor grande em cima, r\u00f3tulo embaixo).\"\"\"\n    stats = (stats or [])[:4]\n    if not stats:\n        return None\n    valst = ParagraphStyle(\"KpiValW\", parent=ss[\"KpiVal\"], textColor=colors.white,\n                           leading=24)\n    labst = ParagraphStyle(\"KpiLabelW\", parent=ss[\"KpiLabel\"], textColor=colors.white,\n                           leading=11)\n    val = [Paragraph(_esc(s.get(\"value\", \"\")), valst) for s in stats]\n    lab = [Paragraph(_esc(s.get(\"label\", \"\")).upper(), labst) for s in stats]\n    w = (170.0 / len(stats)) * mm\n    # Alturas de linha EXPLICITAS: valor (grande) em cima, rotulo embaixo, sem\n    # sobreposicao (VALIGN TOP + padding 0).\n    tbl = Table([val, lab], colWidths=[w] * len(stats), rowHeights=[12 * mm, 7 * mm])\n    tbl.setStyle(_ts([\n        (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n        (\"LEFTPADDING\", (0, 0), (-1, -1), 0),\n        (\"RIGHTPADDING\", (0, 0), (-1, -1), 0),\n        (\"TOPPADDING\", (0, 0), (-1, -1), 0),\n        (\"BOTTOMPADDING\", (0, 0), (-1, -1), 0),\n    ]))\n    return tbl\n\n\ndef _append_image_pdf(S, ss, path, caption=None):\n    if not path or not os.path.exists(path):\n        return False\n    try:\n        iw, ih = ImageReader(path).getSize()\n        maxw, maxh = 160 * mm, 120 * mm\n        scale = min(maxw / iw, maxh / ih, 1.0)\n        img = Image(path, width=iw * scale, height=ih * scale)\n        img.hAlign = \"CENTER\"\n        S.append(Spacer(1, 2 * mm))\n        S.append(img)\n        if caption:\n            S.append(Paragraph(_esc(_clip(caption, 160)), ss[\"Small\"]))\n        S.append(Spacer(1, 3 * mm))\n        return True\n    except Exception:\n        return False\n\n\ndef _placeholder_pdf(S, ss, text):\n    \"\"\"Aviso vis\u00edvel de evid\u00eancia ausente \u2014 nunca pular em sil\u00eancio (WS3).\"\"\"\n    tbl = Table(\n        [[Paragraph(f'<font color=\"#{T.WARNING}\"><b>{_esc(text)}</b></font>',\n                    ss[\"Body2\"])]], colWidths=[165 * mm])\n    tbl.setStyle(_ts([\n        (\"BACKGROUND\", (0, 0), (-1, -1), C(T.SURFACE_ALT)),\n        (\"LINEBEFORE\", (0, 0), (0, -1), 3, C(T.WARNING)),\n        (\"LEFTPADDING\", (0, 0), (-1, -1), 8),\n        (\"TOPPADDING\", (0, 0), (-1, -1), 6),\n        (\"BOTTOMPADDING\", (0, 0), (-1, -1), 6),\n    ]))\n    S.append(tbl)\n    S.append(Spacer(1, 3 * mm))\n\n\ndef _part_divider(ss, sec):\n    out = [PageBreak(), Spacer(1, 40 * mm)]\n    out.append(Paragraph(_esc(sec.get(\"part\", \"\")),\n                         ParagraphStyle(\"pdpart\", parent=ss[\"Small\"],\n                                        fontName=FONT_SANS_BOLD, fontSize=12,\n                                        textColor=C(T.CORAL))))\n    out.append(Paragraph(_esc(sec.get(\"title\", \"\")),\n                         ParagraphStyle(\"pdtitle\", parent=ss[\"Cover\"], fontSize=26)))\n    if sec.get(\"subtitle\"):\n        out.append(Paragraph(_esc(sec[\"subtitle\"]),\n                             ParagraphStyle(\"pdsub\", parent=ss[\"Body2\"],\n                                            fontSize=13, textColor=C(T.MUTED))))\n    return out\n\n\ndef _stat_band(ss, sec):\n    out = []\n    if sec.get(\"headline\"):\n        out.append(Paragraph(_esc(_clip(sec[\"headline\"], 200)),\n                             ParagraphStyle(\"sbh\", parent=ss[\"Cover\"], fontSize=18,\n                                            spaceAfter=6)))\n    st = _stat_table(ss, sec.get(\"stats\"))\n    if st:\n        out += [st, Spacer(1, 5 * mm)]\n    if sec.get(\"body\"):\n        out.append(Paragraph(_ml(sec[\"body\"]), ss[\"Body2\"]))\n    return out\n\n\ndef _attack_chain(ss, sec):\n    out = [Paragraph(\"Cadeia de Ataque\", ss[\"H1\"]),\n           HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6)]\n    boxstyle = ParagraphStyle(\"chainbox\", parent=ss[\"Small\"], fontSize=8,\n                              textColor=C(T.INK), leading=10)\n    arrstyle = ParagraphStyle(\"arr\", parent=ss[\"Small\"], alignment=TA_CENTER)\n    for lane in (sec.get(\"lanes\") or [])[:6]:\n        out.append(Paragraph(_esc(_clip(lane.get(\"title\", \"\"), 120)), ss[\"CardTitle\"]))\n        steps = (lane.get(\"steps\") or [])[:5]\n        cells = []\n        widths = []\n        for i, s in enumerate(steps):\n            cells.append(Paragraph(\n                f'<b><font color=\"#{T.PRIMARY}\">{_esc(_clip(s.get(\"label\", \"\"), 22))}</font></b>'\n                f'<br/><font size=\"7\" color=\"#{T.MUTED}\">{_esc(_clip(s.get(\"detail\", \"\"), 40))}</font>',\n                boxstyle))\n            widths.append(28 * mm)\n            if i < len(steps) - 1:\n                cells.append(Paragraph(f'<font color=\"#{T.CORAL}\" size=\"14\">&#8594;</font>',\n                                       arrstyle))\n                widths.append(6 * mm)\n        if cells:\n            tbl = Table([cells], colWidths=widths)\n            sc = [(\"VALIGN\", (0, 0), (-1, -1), \"MIDDLE\"),\n                  (\"TOPPADDING\", (0, 0), (-1, -1), 5),\n                  (\"BOTTOMPADDING\", (0, 0), (-1, -1), 5),\n                  (\"LEFTPADDING\", (0, 0), (-1, -1), 4),\n                  (\"RIGHTPADDING\", (0, 0), (-1, -1), 4)]\n            for ci in range(0, len(cells), 2):\n                sc.append((\"BACKGROUND\", (ci, 0), (ci, 0), C(T.SURFACE_ALT)))\n                sc.append((\"LINEABOVE\", (ci, 0), (ci, 0), 1.2, C(T.PRIMARY)))\n            tbl.setStyle(_ts(sc))\n            out.append(tbl)\n        out.append(Spacer(1, 4 * mm))\n    return out\n\n\ndef _roadmap(ss, sec):\n    out = [Paragraph(\"Plano de Remedia\u00e7\u00e3o por Fase\", ss[\"H1\"]),\n           HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6)]\n    data = [[Paragraph('<font color=\"white\"><b>Janela</b></font>', ss[\"Body2\"]),\n             Paragraph('<font color=\"white\"><b>Foco</b></font>', ss[\"Body2\"]),\n             Paragraph('<font color=\"white\"><b>A\u00e7\u00f5es</b></font>', ss[\"Body2\"])]]\n    for ph in (sec.get(\"phases\") or [])[:4]:\n        acts = \"<br/>\".join(\"\u2022 \" + _esc(_clip(a, 90))\n                            for a in (ph.get(\"actions\") or [])[:6])\n        data.append([Paragraph(f'<b>{_esc(ph.get(\"window\", \"\"))}</b>', ss[\"Small\"]),\n                     Paragraph(_esc(ph.get(\"label\", \"\")), ss[\"Small\"]),\n                     Paragraph(acts, ss[\"Small\"])])\n    tbl = Table(data, colWidths=[26 * mm, 34 * mm, 114 * mm], repeatRows=1)\n    tbl.setStyle(_ts([\n        (\"BACKGROUND\", (0, 0), (-1, 0), C(T.PRIMARY)),\n        (\"GRID\", (0, 0), (-1, -1), 0.4, C(T.BORDER)),\n        (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n        (\"TOPPADDING\", (0, 0), (-1, -1), 4),\n        (\"BOTTOMPADDING\", (0, 0), (-1, -1), 4),\n    ]))\n    out += [tbl, Spacer(1, 5 * mm)]\n    return out\n\n\ndef _cost_incident(ss, sec):\n    out = [Paragraph(\"Custo da Remedia\u00e7\u00e3o \u00d7 Custo do Incidente\", ss[\"H1\"]),\n           HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6)]\n    remlist = \"<br/>\".join(\"\u2022 \" + _esc(_clip(r, 90))\n                           for r in (sec.get(\"remediation\") or [])[:6])\n    inc_parts = []\n    for it in (sec.get(\"incident\") or [])[:4]:\n        line = f'<b><font color=\"#{T.DESTRUCTIVE}\">\u2022 {_esc(_clip(it.get(\"label\", \"\"), 60))}</font></b>'\n        if it.get(\"detail\"):\n            line += f'<br/><font size=\"8\" color=\"#{T.MUTED}\">   {_esc(_clip(it[\"detail\"], 90))}</font>'\n        inc_parts.append(line)\n    inclist = \"<br/>\".join(inc_parts)\n    header = [Paragraph('<font color=\"white\"><b>REMEDIA\u00c7\u00c3O \u2014 INVESTIMENTO</b></font>', ss[\"Body2\"]),\n              Paragraph('<font color=\"white\"><b>INCIDENTE N\u00c3O REMEDIADO \u2014 RISCO</b></font>', ss[\"Body2\"])]\n    body = [Paragraph(remlist, ss[\"Small\"]), Paragraph(inclist, ss[\"Small\"])]\n    tbl = Table([header, body], colWidths=[87 * mm, 87 * mm])\n    tbl.setStyle(_ts([\n        (\"BACKGROUND\", (0, 0), (0, 0), C(T.SUCCESS)),\n        (\"BACKGROUND\", (1, 0), (1, 0), C(T.DESTRUCTIVE)),\n        (\"BOX\", (0, 0), (-1, -1), 0.5, C(T.BORDER)),\n        (\"INNERGRID\", (0, 0), (-1, -1), 0.5, C(T.BORDER)),\n        (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n        (\"TOPPADDING\", (0, 0), (-1, -1), 6),\n        (\"BOTTOMPADDING\", (0, 0), (-1, -1), 6),\n        (\"LEFTPADDING\", (0, 0), (-1, -1), 6),\n        (\"RIGHTPADDING\", (0, 0), (-1, -1), 6),\n    ]))\n    out += [tbl, Spacer(1, 5 * mm)]\n    return out\n\n\ndef _partner_value(ss, sec):\n    out = [Paragraph(_esc(_clip(sec.get(\"title\", \"Parceria\"), 80)), ss[\"H1\"]),\n           HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6)]\n    for p in (sec.get(\"points\") or [])[:6]:\n        out.append(Paragraph(\n            f'<b><font color=\"#{T.PRIMARY}\">{_esc(_clip(p.get(\"title\", \"\"), 60))}</font></b>',\n            ss[\"Body2\"]))\n        out.append(Paragraph(_esc(_clip(p.get(\"body\", \"\"), 400)), ss[\"Body2\"]))\n    return out\n\n\ndef _next_steps(ss, sec, brand):\n    out = [Paragraph(\"Pr\u00f3ximos Passos\", ss[\"H1\"]),\n           HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6)]\n    for i, s in enumerate((sec.get(\"steps\") or [])[:6], 1):\n        out.append(Paragraph(f'<b>{i}.</b>  {_esc(_clip(s, 200))}',\n                             ParagraphStyle(\"ns\", parent=ss[\"Body2\"], fontSize=12,\n                                            spaceAfter=4)))\n    contact = \" \u00b7 \".join([x for x in [brand.get(\"name\", \"\"), brand.get(\"contact\", \"\"),\n                                      brand.get(\"tagline\", \"\")] if x])\n    if contact:\n        out.append(Spacer(1, 4 * mm))\n        out.append(Paragraph(_esc(contact), ss[\"Small\"]))\n    return out\n\n\ndef render_pdf(model, out_path):\n    meta = model.get(\"meta\", {})\n    _apply_brand(meta)\n    ss = _styles()\n    toc = TableOfContents()\n    toc.levelStyles = [\n        ParagraphStyle(\"TOCl0\", fontName=FONT_SANS_BOLD, fontSize=12, leading=20,\n                       textColor=C(T.INK)),\n        ParagraphStyle(\"TOCl1\", fontName=FONT_SANS, fontSize=10.5, leading=17,\n                       leftIndent=14, textColor=C(T.INK)),\n        ParagraphStyle(\"TOCl2\", fontName=FONT_SANS, fontSize=10, leading=15,\n                       leftIndent=28, textColor=C(T.MUTED)),\n    ]\n    # O Table interno do TOC herda FONTNAME 'Helvetica' do TableStyle padr\u00e3o\n    # (embutiria Helvetica no PDF e quebraria a pureza de fonte do dossi\u00ea) \u2014\n    # for\u00e7a IBM Plex.\n    toc.tableStyle = TableStyle([\n        (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n        (\"LEFTPADDING\", (0, 0), (-1, -1), 0),\n        (\"RIGHTPADDING\", (0, 0), (-1, -1), 0),\n        (\"FONTNAME\", (0, 0), (-1, -1), FONT_SANS),\n    ])\n    S = []\n    title = None\n    brand = meta.get(\"brand\", {})\n    # Capa: arte da marca (coverImagePath) OU, na aus\u00eancia, o navy PADR\u00c3O (gold\n    # SYN) \u2014 mesmo tratamento do DOCX. O fundo \u00e9 desenhado no canvas (page 1);\n    # _cover_navy_default avisa o bloco da capa p/ usar texto/logo/KPIs BRANCOS.\n    _cover_bg = brand.get(\"coverImagePath\")\n    _cover_navy_default = False\n    if not (_cover_bg and os.path.exists(_cover_bg)):\n        try:\n            _cover_bg = T.default_cover_bg()\n            _cover_navy_default = bool(_cover_bg and os.path.exists(_cover_bg))\n        except Exception:\n            _cover_bg = None\n            _cover_navy_default = False\n\n    def esc(s):\n        return _esc(s)\n\n    for sec in model.get(\"sections\", []):\n        t = sec.get(\"type\")\n        if t == \"cover\" and brand.get(\"coverImagePath\") and os.path.exists(brand[\"coverImagePath\"]):\n            # Arte full-bleed desenhada no canvas; sobrepomos o t\u00edtulo em branco.\n            S.append(Spacer(1, 150 * mm))\n            S.append(Paragraph(\n                f'<b><font color=\"#FFFFFF\">{esc(meta.get(\"classification\",\"\"))}   \u00b7   {esc(meta.get(\"docCode\",\"\"))}</font></b>',\n                ss[\"Small\"]))\n            S.append(Paragraph(\n                f'<font color=\"#FFFFFF\"><b>{esc(meta.get(\"volume\",\"\"))}</b></font>',\n                ss[\"Small\"]))\n            S.append(Spacer(1, 6 * mm))\n            S.append(Paragraph(\n                f'<font color=\"#FFFFFF\">{esc(sec.get(\"title\",\"\"))}</font>',\n                ss[\"Cover\"]))\n            if sec.get(\"subtitle\"):\n                S.append(Paragraph(\n                    f'<font color=\"#FFFFFF\">{esc(sec[\"subtitle\"])}</font>',\n                    ParagraphStyle(\"subl\", parent=ss[\"Body2\"], fontSize=13,\n                                   textColor=colors.white)))\n            S.append(PageBreak())\n            S += _summary_block(ss, toc)\n        elif t == \"cover\":\n            # Sem arte da marca \u2192 capa NAVY padr\u00e3o (gold SYN): texto/logo/KPIs em\n            # BRANCO sobre o navy desenhado no canvas. Se o navy n\u00e3o p\u00f4de ser\n            # gerado (_cover_navy_default=False), degrada p/ a capa clara (INK).\n            _ctitle = \"FFFFFF\" if _cover_navy_default else T.INK\n            _cmuted = \"C9D3E6\" if _cover_navy_default else T.MUTED\n            S.append(Spacer(1, 30 * mm))\n            used_logo = False\n            logo_path = brand.get(\"logoPath\")\n            if logo_path and os.path.exists(logo_path):\n                try:\n                    iw, ih = ImageReader(logo_path).getSize()\n                    w = 60 * mm\n                    h = w * ih / iw\n                    if h > 24 * mm:\n                        h = 24 * mm\n                        w = h * iw / ih\n                    im = Image(logo_path, width=w, height=h)\n                    im.hAlign = \"LEFT\"\n                    S.append(im)\n                    used_logo = True\n                except Exception:\n                    used_logo = False\n            if not used_logo and brand.get(\"wordmark\", \"\") == \"Suricatoos\":\n                lp = logo.write_logo(dark=_cover_navy_default)  # branco no navy\n                if lp and os.path.exists(lp):\n                    try:\n                        # Altura do ratio REAL do PNG (logo oficial 1600x274).\n                        _iw, _ih = ImageReader(lp).getSize()\n                        _w = 70 * mm\n                        im = Image(lp, width=_w, height=_w * _ih / _iw)\n                        im.hAlign = \"LEFT\"\n                        S.append(im)\n                        used_logo = True\n                    except Exception:\n                        used_logo = False\n            if not used_logo:\n                S.append(Paragraph(\n                    f'<font color=\"#{_ctitle}\">{esc(brand.get(\"wordmark\", T.WORDMARK))}</font>',\n                    ss[\"Wordmark\"]))\n            S.append(Spacer(1, 55 * mm))\n            S.append(Paragraph(\n                f'<b><font color=\"#{T.CORAL}\">{esc(meta.get(\"classification\", \"\"))}   \u00b7   {esc(meta.get(\"docCode\", \"\"))}</font></b>',\n                ss[\"Small\"]))\n            S.append(Paragraph(\n                f'<font color=\"#{_cmuted}\"><b>{esc(meta.get(\"volume\", \"\"))}</b></font>',\n                ss[\"Small\"]))\n            S.append(Spacer(1, 8 * mm))\n            S.append(Paragraph(\n                f'<font color=\"#{_ctitle}\">{esc(sec.get(\"title\", \"\"))}</font>',\n                ss[\"Cover\"]))\n            if sec.get(\"subtitle\"):\n                S.append(Paragraph(\n                    f'<font color=\"#{_cmuted}\">{esc(sec[\"subtitle\"])}</font>',\n                    ParagraphStyle(\"sub\", parent=ss[\"Body2\"], fontSize=13)))\n            S.append(Spacer(1, 12 * mm))\n            st = (_stat_table_white if _cover_navy_default else _stat_table)(\n                ss, sec.get(\"stats\"))\n            if st:\n                S.append(st)\n            S.append(PageBreak())\n            S += _summary_block(ss, toc)\n        elif t == \"partDivider\":\n            S += _part_divider(ss, sec)\n        elif t == \"divider\":\n            S.append(PageBreak())\n        elif t == \"heading\":\n            title = sec.get(\"text\")\n            _hname = \"TOCH2\" if sec.get(\"level\", 1) == 2 else \"TOCH1\"\n            S.append(Paragraph(esc(sec.get(\"text\", \"\")),\n                               ParagraphStyle(_hname, parent=ss[\"H1\"])))\n            S.append(HRFlowable(width=\"18%\", thickness=2, color=C(T.CORAL), spaceAfter=6))\n        elif t == \"paragraph\":\n            S.append(Paragraph(_ml(sec.get(\"text\", \"\")), ss[\"Body2\"]))\n        elif t == \"bullets\":\n            for it in sec.get(\"items\", []):\n                S.append(Paragraph(\"\u2022 \" + _ml(it), ss[\"Body2\"]))\n        elif t == \"statBand\":\n            S += _stat_band(ss, sec)\n        elif t == \"kpis\":\n            k = sec.get(\"kpis\", {})\n            bysev = k.get(\"bySeverity\", {})\n            data = [\n                [Paragraph(\"TOTAL\", ss[\"KpiLabel\"]), Paragraph(\"RISCO\", ss[\"KpiLabel\"]),\n                 Paragraph(\"CVSS M\u00c9DIO\", ss[\"KpiLabel\"]), Paragraph(\"CRIT+ALTO\", ss[\"KpiLabel\"])],\n                [Paragraph(str(k.get(\"total\", 0)), ss[\"KpiVal\"]),\n                 Paragraph(str(k.get(\"riskScore\", 0)), ss[\"KpiVal\"]),\n                 Paragraph(str(k.get(\"avgCvss\") if k.get(\"avgCvss\") is not None else \"-\"), ss[\"KpiVal\"]),\n                 Paragraph(str(bysev.get(\"critical\", 0) + bysev.get(\"high\", 0)), ss[\"KpiVal\"])],\n            ]\n            tbl = Table(data, colWidths=[42 * mm] * 4)\n            tbl.setStyle(_ts([\n                (\"BACKGROUND\", (0, 0), (-1, -1), C(T.SURFACE_ALT)),\n                (\"BOX\", (0, 0), (-1, -1), 0.5, C(T.BORDER)),\n                (\"INNERGRID\", (0, 0), (-1, -1), 0.5, C(T.SURFACE)),\n                (\"TOPPADDING\", (0, 0), (-1, -1), 8),\n                (\"BOTTOMPADDING\", (0, 0), (-1, -1), 8),\n            ]))\n            S.append(tbl)\n            S.append(Spacer(1, 6 * mm))\n        elif t == \"severityChart\":\n            dist = sec.get(\"data\", {}).get(\"severityDistribution\", [])\n            maxc = max([d.get(\"count\", 0) for d in dist] + [1])\n            rows = []\n            style = [(\"BOX\", (0, 0), (-1, -1), 0, C(T.SURFACE))]\n            for i, d in enumerate(dist):\n                sev = d.get(\"severity\")\n                c = d.get(\"count\", 0)\n                bar = \"\u2588\" * int(round((c / maxc) * 24)) if c > 0 else \"\"\n                rows.append([Paragraph(T.SEVERITY_LABEL.get(sev, sev), ss[\"Body2\"]),\n                             Paragraph(f'<font color=\"#{T.SEVERITY_COLOR.get(sev, T.MUTED)}\">{bar}</font> {c}', ss[\"Body2\"])])\n            tbl = Table(rows, colWidths=[35 * mm, 130 * mm])\n            tbl.setStyle(_ts(style))\n            S.append(tbl)\n            S.append(Spacer(1, 5 * mm))\n        elif t == \"riskMatrix\":\n            cells = {(c[\"likelihood\"], c[\"impact\"]): c.get(\"count\", 0)\n                     for c in sec.get(\"data\", {}).get(\"riskMatrix\", [])}\n            data = []\n            stylecmds = [(\"ALIGN\", (0, 0), (-1, -1), \"CENTER\"),\n                         (\"VALIGN\", (0, 0), (-1, -1), \"MIDDLE\"),\n                         (\"TEXTCOLOR\", (0, 0), (-1, -1), colors.white),\n                         (\"FONTSIZE\", (0, 0), (-1, -1), 11)]\n            for r in range(5):\n                li = 5 - r\n                row = []\n                for col in range(5):\n                    im = col + 1\n                    cnt = cells.get((li, im), 0)\n                    row.append(str(cnt) if cnt else \"\")\n                    stylecmds.append((\"BACKGROUND\", (col, r), (col, r), C(_band(li + im))))\n                data.append(row)\n            tbl = Table(data, colWidths=[22 * mm] * 5, rowHeights=[16 * mm] * 5)\n            tbl.setStyle(_ts(stylecmds))\n            S.append(tbl)\n            S.append(Paragraph(\"Probabilidade (linhas) \u00d7 Impacto (colunas)\", ss[\"Small\"]))\n            S.append(Spacer(1, 5 * mm))\n        elif t == \"attackChain\":\n            S += _attack_chain(ss, sec)\n        elif t == \"findingCard\":\n            f = sec[\"finding\"]\n            sev = f.get(\"severity\", \"info\")\n            S.append(Paragraph(\n                f'<font color=\"#{T.SEVERITY_COLOR.get(sev, T.MUTED)}\"><b>[{T.SEVERITY_LABEL.get(sev, sev).upper()}]</b></font> '\n                f'{esc(f.get(\"ref\",\"\"))} \u00b7 {esc(_clip(f.get(\"title\",\"\"),200))}', ss[\"CardTitle\"]))\n            meta_bits = []\n            if f.get(\"affectedAsset\"):\n                meta_bits.append(f\"Ativo: {esc(f['affectedAsset'])}\")\n            if f.get(\"weaknessClass\"):\n                meta_bits.append(f\"Classe: {esc(f['weaknessClass'])}\")\n            if f.get(\"cvssVector\"):\n                meta_bits.append(f\"CVSS: {esc(f['cvssVector'])}\")\n            if f.get(\"cwe\"):\n                meta_bits.append(f\"CWE: {esc(f['cwe'])}\")\n            if meta_bits:\n                S.append(Paragraph(\"   \".join(meta_bits), ss[\"Small\"]))\n            if f.get(\"narrative\"):\n                S.append(Paragraph(f'<b><font color=\"#{T.PRIMARY}\">Narrativa:</font></b> {_ml(f[\"narrative\"])}', ss[\"Body2\"]))\n            for label, key in [(\"Descri\u00e7\u00e3o\", \"description\"), (\"Impacto\", \"impact\"), (\"Remedia\u00e7\u00e3o\", \"remediation\")]:\n                if f.get(key):\n                    S.append(Paragraph(f'<b><font color=\"#{T.PRIMARY}\">{label}:</font></b> {_ml(f[key])}', ss[\"Body2\"]))\n            if sec.get(\"showPoc\") and f.get(\"reproductionSteps\"):\n                S.append(Paragraph(f'<b><font color=\"#{T.PRIMARY}\">Reprodu\u00e7\u00e3o:</font></b>', ss[\"Body2\"]))\n                for i, s in enumerate(f[\"reproductionSteps\"], 1):\n                    S.append(Paragraph(f\"{i}. {_ml(s)}\", ss[\"Body2\"]))\n            if sec.get(\"showPoc\"):\n                ev = sorted(\n                    f.get(\"evidence\") or [],\n                    key=lambda e: e.get(\"stepIndex\") if e.get(\"stepIndex\") is not None else 1_000_000,\n                )\n                if any(e.get(\"snippet\") or e.get(\"imagePath\") or e.get(\"command\") for e in ev):\n                    S.append(Paragraph(f'<b><font color=\"#{T.PRIMARY}\">Cadeia de evid\u00eancia:</font></b>', ss[\"Body2\"]))\n                img_rendered = 0\n                for i, e in enumerate(ev, 1):\n                    n = e.get(\"stepIndex\") or i\n                    head = f\"<b>{n}.</b>\"\n                    if e.get(\"toolName\"):\n                        head += f' <font face=\"{FONT_MONO}\">[{esc(e[\"toolName\"])}]</font>'\n                    if e.get(\"label\") and e.get(\"label\") != e.get(\"toolName\"):\n                        head += f' {esc(_clip(e[\"label\"],160))}'\n                    S.append(Paragraph(head, ss[\"Small\"]))\n                    if e.get(\"command\"):\n                        S.append(Paragraph(\"$ \" + _ml(e[\"command\"]), ss[\"Mono\"]))\n                    if e.get(\"snippet\"):\n                        S.append(Paragraph(_ml(e[\"snippet\"]), ss[\"Mono\"]))\n                    if e.get(\"resultSummary\"):\n                        S.append(Paragraph(f'<font color=\"#{T.SUCCESS}\"><b>&#8594; prova:</b></font> {_ml(e[\"resultSummary\"])}', ss[\"Small\"]))\n                    if e.get(\"imagePath\"):\n                        if _append_image_pdf(S, ss, e[\"imagePath\"], e.get(\"label\")):\n                            img_rendered += 1\n                        else:\n                            _placeholder_pdf(S, ss, \"\u26a0 Evid\u00eancia visual referenciada n\u00e3o dispon\u00edvel no pacote.\")\n                if img_rendered == 0 and sev in (\"critical\", \"high\"):\n                    if any(e.get(\"imageUnavailable\") for e in ev):\n                        _placeholder_pdf(S, ss, \"\u26a0 Evid\u00eancia visual capturada, por\u00e9m indispon\u00edvel (expirada/removida do armazenamento).\")\n                    else:\n                        _placeholder_pdf(S, ss, \"\u26a0 Evid\u00eancia visual n\u00e3o capturada para este achado.\")\n        elif t in (\"findingsTable\", \"remediationMatrix\"):\n            findings = sec.get(\"findings\", [])\n            rem = t == \"remediationMatrix\"\n            headers = ([\"Ref\", \"Sev\", \"Ativo\", \"Remedia\u00e7\u00e3o\"] if rem\n                       else [\"Ref\", \"Sev\", \"T\u00edtulo\", \"Ativo\", \"CVSS\"])\n            data = [headers]\n            for f in findings:\n                sev = f.get(\"severity\", \"info\")\n                cvss = f.get(\"cvssScore\")\n                cvss_s = f\"{cvss:.1f}\" if isinstance(cvss, (int, float)) else \"\u2014\"\n                data.append(\n                    [f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                     _clip(f.get(\"affectedAsset\", \"\"), 40), _clip(f.get(\"remediation\", \"\"), 110)]\n                    if rem else\n                    [f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                     _clip(f.get(\"title\", \"\"), 58), _clip(f.get(\"affectedAsset\", \"\"), 34), cvss_s])\n            widths = ([16 * mm, 18 * mm, 45 * mm, 86 * mm] if rem\n                      else [15 * mm, 17 * mm, 70 * mm, 42 * mm, 16 * mm])\n            tbl = Table(data, colWidths=widths, repeatRows=1)\n            tbl.setStyle(_ts([\n                (\"BACKGROUND\", (0, 0), (-1, 0), C(T.PRIMARY)),\n                (\"TEXTCOLOR\", (0, 0), (-1, 0), colors.white),\n                (\"FONTNAME\", (0, 0), (-1, 0), FONT_SANS_BOLD),\n                (\"FONTSIZE\", (0, 0), (-1, -1), 8.5),\n                (\"GRID\", (0, 0), (-1, -1), 0.4, C(T.BORDER)),\n                (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n                (\"TOPPADDING\", (0, 0), (-1, -1), 3),\n                (\"BOTTOMPADDING\", (0, 0), (-1, -1), 3),\n            ]))\n            S.append(tbl)\n            S.append(Spacer(1, 5 * mm))\n        elif t == \"roadmap\":\n            S += _roadmap(ss, sec)\n        elif t == \"costVsIncident\":\n            S += _cost_incident(ss, sec)\n        elif t == \"partnerValue\":\n            S += _partner_value(ss, sec)\n        elif t == \"nextSteps\":\n            S += _next_steps(ss, sec, brand)\n        elif t == \"callout\":\n            col = T.CALLOUT_COLOR.get(sec.get(\"tone\", \"info\"), T.PRIMARY)\n            tbl = Table([[Paragraph(f'<font color=\"#{col}\"><b>{_ml(sec.get(\"text\",\"\"))}</b></font>', ss[\"Body2\"])]],\n                        colWidths=[165 * mm])\n            tbl.setStyle(_ts([\n                (\"BACKGROUND\", (0, 0), (-1, -1), C(T.SURFACE_ALT)),\n                (\"LINEBEFORE\", (0, 0), (0, -1), 3, C(col)),\n                (\"LEFTPADDING\", (0, 0), (-1, -1), 8),\n                (\"TOPPADDING\", (0, 0), (-1, -1), 6),\n                (\"BOTTOMPADDING\", (0, 0), (-1, -1), 6),\n            ]))\n            S.append(tbl)\n            S.append(Spacer(1, 5 * mm))\n\n    foot = _cover_canvas_factory(meta, _cover_bg)\n    doc = _TocDocTemplate(out_path, foot, pagesize=A4, leftMargin=18 * mm,\n                          rightMargin=18 * mm, topMargin=16 * mm,\n                          bottomMargin=16 * mm, title=\"Relat\u00f3rio\")\n    doc.multiBuild(S)\n",
  "pptx_renderer.py": "\"\"\"Renderer PPTX (python-pptx) do ReportModel \u2014 estilo \"dossie\".\n\nCasca de dossie: capa com codigo de documento + selo + faixa de KPIs, rodape\nnumerado (CONFIDENCIAL \u00b7 docCode \u00b7 NN), divisorias de PARTE. Marca configuravel\npor MSSP (meta.brand sobrescreve a paleta/wordmark). Cada secao de conteudo\nvira um slide.\"\"\"\n\nfrom pptx import Presentation\nfrom pptx.util import Inches, Pt, Emu\nfrom pptx.dml.color import RGBColor\nfrom pptx.enum.text import PP_ALIGN, MSO_ANCHOR, MSO_AUTO_SIZE\nfrom pptx.enum.shapes import MSO_SHAPE\nimport os\n\nimport theme as T\nimport logo\n\nEMU_IN = 914400\nSW = Inches(13.333)\nSH = Inches(7.5)\nML = Inches(0.6)\nCW = Inches(12.13)\n\nMONTHS = [\"JANEIRO\", \"FEVEREIRO\", \"MAR\u00c7O\", \"ABRIL\", \"MAIO\", \"JUNHO\", \"JULHO\",\n          \"AGOSTO\", \"SETEMBRO\", \"OUTUBRO\", \"NOVEMBRO\", \"DEZEMBRO\"]\n\n# Estado por render (um modelo por processo): meta p/ rodape + contador de pagina.\n_STATE = {\"meta\": {}, \"page\": 0}\n\n\ndef _rgb(hexstr):\n    return RGBColor.from_string(hexstr)\n\n\ndef _blank(prs):\n    return prs.slides.add_slide(prs.slide_layouts[6])\n\n\ndef _accent():\n    return _STATE[\"meta\"].get(\"brand\", {}).get(\"accent\") or T.CORAL\n\n\ndef _month_year(ms):\n    try:\n        import datetime\n        d = datetime.datetime.utcfromtimestamp(int(ms) / 1000)\n        return f\"{MONTHS[d.month - 1]} \u00b7 {d.year}\"\n    except Exception:\n        return \"\"\n\n\ndef _text(slide, l, t, w, h, text, size=14, bold=False, color=T.INK,\n          align=PP_ALIGN.LEFT, font=T.FONT_BODY, anchor=MSO_ANCHOR.TOP):\n    tb = slide.shapes.add_textbox(l, t, w, h)\n    tf = tb.text_frame\n    tf.word_wrap = True\n    tf.vertical_anchor = anchor\n    lines = str(text).split(\"\\n\")\n    for i, ln in enumerate(lines):\n        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()\n        p.alignment = align\n        r = p.add_run()\n        r.text = ln\n        r.font.size = Pt(size)\n        r.font.bold = bold\n        r.font.name = font\n        r.font.color.rgb = _rgb(color)\n    return tb\n\n\ndef _rect(slide, l, t, w, h, fill, line=None):\n    sp = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, l, t, w, h)\n    sp.fill.solid()\n    sp.fill.fore_color.rgb = _rgb(fill)\n    if line:\n        sp.line.color.rgb = _rgb(line)\n        sp.line.width = Pt(0.75)\n    else:\n        sp.line.fill.background()\n    sp.shadow.inherit = False\n    return sp\n\n\ndef _clip(s, n):\n    s = str(s or \"\")\n    return s if len(s) <= n else s[: n - 1] + \"\u2026\"\n\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Motor de layout com pagina\u00e7\u00e3o (WS2): PPTX n\u00e3o mede texto, ent\u00e3o estimamos\n# linhas por caixa e quebramos conte\u00fado longo em slides \"(cont.)\" \u2014 NUNCA\n# truncamos corpo de achado/evid\u00eancia. Unidades em EMU (int).\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n_CONTENT_BOTTOM = int(Inches(6.95))   # acima do rodap\u00e9 (7.08)\n_LINE_FACTOR = 1.3                      # entrelinha aproximada\n\n\ndef _wrap(text, cpl):\n    \"\"\"Quebra texto em linhas de ~cpl chars, respeitando \\\\n e palavras longas.\"\"\"\n    out = []\n    for raw in str(text or \"\").split(\"\\n\"):\n        if not raw:\n            out.append(\"\")\n            continue\n        line = \"\"\n        for w in raw.split(\" \"):\n            while len(w) > cpl:               # token gigante \u2192 quebra for\u00e7ada\n                if line:\n                    out.append(line)\n                    line = \"\"\n                out.append(w[:cpl])\n                w = w[cpl:]\n            cand = w if not line else line + \" \" + w\n            if len(cand) <= cpl:\n                line = cand\n            else:\n                out.append(line)\n                line = w\n        out.append(line)\n    return out\n\n\ndef _img_size(path):\n    try:\n        from PIL import Image\n        with Image.open(path) as im:\n            return im.size\n    except Exception:\n        return None\n\n\nclass _Flow:\n    \"\"\"Cursor de conte\u00fado que flui slide a slide, abrindo continua\u00e7\u00f5es.\"\"\"\n\n    def __init__(self, prs, title):\n        self.prs = prs\n        self.title = title\n        self.slide, y = _title_slide(prs, title)\n        self.y = int(y)\n\n    def _newslide(self):\n        self.slide, y = _title_slide(self.prs, _clip(self.title, 58) + \" (cont.)\")\n        self.y = int(y)\n\n    def space(self, emu):\n        self.y += int(emu)\n\n    def ensure(self, emu):\n        if self.y + int(emu) > _CONTENT_BOTTOM:\n            self._newslide()\n\n    def heading(self, text, size=12, color=None):\n        color = color or T.PRIMARY\n        self.ensure(Inches(0.5))\n        _text(self.slide, ML, Emu(self.y), CW, Inches(0.32), text, size=size,\n              bold=True, color=color)\n        self.y += int(Inches(0.42))\n\n    def para(self, text, size=11, color=T.INK, bold=False, font=T.FONT_BODY,\n             indent=0.0, after=0.08):\n        left = int(ML) + int(Inches(indent))\n        width = int(CW) - int(Inches(indent))\n        # Largura m\u00e9dia por caractere CONSERVADORA (em \"em\"): proporcional ~0.58,\n        # mono ~0.63, + bold. Subcontar linhas causa estouro/sobreposi\u00e7\u00e3o (a caixa\n        # de altura fixa transborda e o bloco seguinte sobrep\u00f5e); superestimar s\u00f3\n        # deixa folga. _wrap controla TODAS as quebras e word_wrap=False impede o\n        # PowerPoint de RE-quebrar uma linha (a cascata que gerava a sobreposi\u00e7\u00e3o).\n        cwf = (0.63 if font == T.FONT_MONO else 0.58) + (0.04 if bold else 0.0)\n        cpl = max(8, int((width / EMU_IN) * 72 / (size * cwf)))\n        lines = _wrap(text, cpl)\n        lh = int(size * _LINE_FACTOR / 72.0 * EMU_IN)\n        i = 0\n        while i < len(lines):\n            self.ensure(lh)\n            cap = max(1, (_CONTENT_BOTTOM - self.y) // lh)\n            take = lines[i:i + cap]\n            i += len(take)\n            h = len(take) * lh\n            tb = self.slide.shapes.add_textbox(Emu(left), Emu(self.y),\n                                               Emu(width), Emu(h))\n            tf = tb.text_frame\n            tf.word_wrap = False\n            try:\n                tf.auto_size = MSO_AUTO_SIZE.NONE\n            except Exception:\n                pass\n            for j, ln in enumerate(take):\n                p = tf.paragraphs[0] if j == 0 else tf.add_paragraph()\n                r = p.add_run()\n                r.text = ln\n                r.font.size = Pt(size)\n                r.font.bold = bold\n                r.font.name = font\n                r.font.color.rgb = _rgb(color)\n            self.y += h\n        self.y += int(Inches(after))\n\n    def image(self, path, caption=None):\n        \"\"\"Embute imagem escalada \u00e0 coluna; paginando. Retorna True se embutiu.\"\"\"\n        sz = _img_size(path)\n        if not sz or not path or not os.path.exists(path):\n            return False\n        iw, ih = sz\n        maxw, maxh = int(CW), int(Inches(4.6))\n        scale = min(maxw / iw, maxh / ih)\n        w, h = int(iw * scale), int(ih * scale)\n        self.ensure(h + int(Inches(0.1)))\n        left = int(ML) + (int(CW) - w) // 2\n        try:\n            self.slide.shapes.add_picture(path, Emu(left), Emu(self.y),\n                                          width=Emu(w), height=Emu(h))\n        except Exception:\n            return False\n        self.y += h + int(Inches(0.08))\n        if caption:\n            self.para(\"\u25b2 \" + str(caption), size=10, color=T.MUTED, after=0.14)\n        return True\n\n    def placeholder(self, text, tone=None):\n        tone = tone or T.WARNING\n        self.ensure(Inches(0.6))\n        _rect(self.slide, ML, Emu(self.y), CW, Inches(0.5), T.SURFACE_ALT,\n              line=tone)\n        _text(self.slide, ML + Inches(0.15), Emu(self.y), CW - Inches(0.3),\n              Inches(0.5), text, size=11, bold=True, color=tone,\n              anchor=MSO_ANCHOR.MIDDLE)\n        self.y += int(Inches(0.62))\n\n\ndef _footer(slide, dark=False):\n    \"\"\"Rodape numerado em todo slide de conteudo (cover nao chama).\"\"\"\n    m = _STATE[\"meta\"]\n    _STATE[\"page\"] += 1\n    n = _STATE[\"page\"]\n    col = \"8FA0BC\" if dark else T.MUTED\n    _text(slide, ML, Inches(7.08), Inches(6.0), Inches(0.3),\n          m.get(\"classification\", \"\"), size=8, color=col)\n    _text(slide, Inches(9.0), Inches(7.08), Inches(3.73), Inches(0.3),\n          f\"{m.get('docCode', '')} \u00b7 {n:02d}\", size=8, color=col,\n          align=PP_ALIGN.RIGHT)\n\n\ndef _title_slide(prs, title):\n    slide = _blank(prs)\n    _rect(slide, 0, 0, SW, Inches(0.12), T.PRIMARY)\n    title = _clip(str(title or \"\"), 104)\n    # T\u00edtulo longo encolhe (24\u219218pt) p/ caber na faixa ACIMA do tra\u00e7o coral, sem\n    # a 2\u00aa linha invadir o acento (bug: t\u00edtulos de achado cruzavam o tra\u00e7o).\n    tsize = 24 if len(title) <= 56 else 18\n    _text(slide, ML, Inches(0.33), CW, Inches(0.68), title, size=tsize, bold=True,\n          color=T.INK, font=T.FONT_DISPLAY)\n    _rect(slide, ML, Inches(1.08), Inches(1.2), Emu(int(0.045 * EMU_IN)), _accent())\n    _footer(slide)\n    return slide, Inches(1.4)\n\n\ndef _cover(prs, sec, meta):\n    slide = _blank(prs)\n    brand = meta.get(\"brand\", {})\n    accent = brand.get(\"accent\") or T.CORAL\n    # Capa full-bleed: arte da marca (coverImagePath) ao fundo; sen\u00e3o, navy s\u00f3lido.\n    cover = brand.get(\"coverImagePath\")\n    if not (cover and os.path.exists(cover)):\n        # Sem arte da marca \u2192 navy PADR\u00c3O (gold SYN): mesma arte do DOCX/PDF\n        # (navy INK + faixa azul + tra\u00e7o coral), em vez do ret\u00e2ngulo s\u00f3lido.\n        try:\n            cover = T.default_cover_bg()\n        except Exception:\n            cover = None\n    if cover and os.path.exists(cover):\n        try:\n            fitted = T.cover_fit(cover, int(SW), int(SH))\n            slide.shapes.add_picture(fitted, 0, 0, width=SW, height=SH)\n        except Exception:\n            _rect(slide, 0, 0, SW, SH, T.INK)\n    else:\n        _rect(slide, 0, 0, SW, SH, T.INK)\n    # Wordmark (topo-esq): logo custom da marca > logo Suricatoos embutido > texto.\n    used_logo = False\n    logo_path = brand.get(\"logoPath\")\n    if logo_path and os.path.exists(logo_path):\n        try:\n            slide.shapes.add_picture(logo_path, ML, Inches(0.5), height=Inches(0.6))\n            used_logo = True\n        except Exception:\n            used_logo = False\n    if not used_logo and brand.get(\"wordmark\", \"\") == \"Suricatoos\":\n        lp = logo.write_logo(dark=True)\n        if lp and os.path.exists(lp):\n            try:\n                slide.shapes.add_picture(lp, ML, Inches(0.5), height=Inches(0.5))\n                used_logo = True\n            except Exception:\n                used_logo = False\n    if not used_logo:\n        _text(slide, ML, Inches(0.5), Inches(7.0), Inches(0.5),\n              brand.get(\"wordmark\", T.WORDMARK), size=22, bold=True,\n              color=accent, font=T.FONT_DISPLAY)\n    # Topo-dir: selo + codigo do documento.\n    _text(slide, Inches(7.9), Inches(0.5), Inches(4.83), Inches(0.3),\n          meta.get(\"classification\", \"\"), size=10, bold=True, color=accent,\n          align=PP_ALIGN.RIGHT)\n    _text(slide, Inches(7.9), Inches(0.85), Inches(4.83), Inches(0.3),\n          meta.get(\"docCode\", \"\"), size=10, color=\"8FA0BC\", align=PP_ALIGN.RIGHT)\n    # Titulo.\n    _rect(slide, ML, Inches(2.2), Inches(1.4), Emu(int(0.06 * EMU_IN)), accent)\n    _text(slide, ML, Inches(2.35), CW, Inches(0.35), meta.get(\"volume\", \"\"),\n          size=12, bold=True, color=accent)\n    _text(slide, ML, Inches(2.75), CW, Inches(1.3), sec.get(\"title\", \"\"),\n          size=40, bold=True, color=\"FFFFFF\", font=T.FONT_DISPLAY)\n    if sec.get(\"subtitle\"):\n        _text(slide, ML, Inches(4.1), CW, Inches(0.6), sec[\"subtitle\"], size=18,\n              color=\"C9D3E6\")\n    # Faixa de KPIs.\n    stats = sec.get(\"stats\") or []\n    if stats:\n        tw = Inches(2.7)\n        gap = Inches(0.2)\n        yv = Inches(5.15)\n        for i, s in enumerate(stats[:4]):\n            x = ML + (tw + gap) * i\n            _text(slide, x, yv, tw, Inches(0.8), str(s.get(\"value\", \"\")),\n                  size=40, bold=True, color=accent, font=T.FONT_DISPLAY)\n            _text(slide, x, yv + Inches(0.85), tw, Inches(0.5),\n                  str(s.get(\"label\", \"\")), size=10, bold=True, color=\"8FA0BC\")\n    # Rodape da capa.\n    _text(slide, ML, Inches(6.85), CW, Inches(0.4),\n          f\"{meta.get('client', '')}  \u00b7  {_month_year(meta.get('generatedAt', 0))}  \u00b7  {brand.get('name', '')}\",\n          size=12, color=\"C9D3E6\")\n    _STATE[\"page\"] = 1\n\n\ndef _part_divider(prs, sec):\n    slide = _blank(prs)\n    _rect(slide, 0, 0, SW, SH, T.INK)\n    accent = _accent()\n    _rect(slide, ML, Inches(3.0), Inches(1.6), Emu(int(0.06 * EMU_IN)), accent)\n    _text(slide, ML, Inches(2.35), CW, Inches(0.4), sec.get(\"part\", \"\"),\n          size=14, bold=True, color=accent)\n    _text(slide, ML, Inches(3.2), CW, Inches(1.2), sec.get(\"title\", \"\"),\n          size=34, bold=True, color=\"FFFFFF\", font=T.FONT_DISPLAY)\n    if sec.get(\"subtitle\"):\n        _text(slide, ML, Inches(4.5), CW, Inches(0.6), sec[\"subtitle\"],\n              size=16, color=\"C9D3E6\")\n    _footer(slide, dark=True)\n\n\ndef _divider(prs, meta):\n    slide = _blank(prs)\n    _rect(slide, 0, 0, SW, SH, T.SURFACE_ALT)\n    _rect(slide, ML, Inches(3.4), Inches(1.6), Emu(int(0.06 * EMU_IN)), _accent())\n    _text(slide, ML, Inches(3.6), CW, Inches(0.6),\n          meta.get(\"brand\", {}).get(\"wordmark\", T.WORDMARK), size=22,\n          bold=True, color=T.PRIMARY, font=T.FONT_DISPLAY)\n    _footer(slide)\n\n\ndef _agenda(prs, entries, meta):\n    \"\"\"Slide SUM\u00c1RIO: partes (n\u00edvel 0, negrito) + se\u00e7\u00f5es/fases (n\u00edveis 1-2,\n    recuadas). entries = [(title, level)]. Duas colunas quando longo (evita\n    overflow \u2014 ver hist\u00f3rico de estouro no PPTX).\"\"\"\n    lines = [(str(t), lv) for (t, lv) in (entries or []) if t]\n    if not lines:\n        return\n    slide = _blank(prs)\n    _rect(slide, 0, 0, SW, Inches(0.12), T.PRIMARY)\n    _text(slide, ML, Inches(0.5), CW, Inches(0.8), \"SUM\u00c1RIO\", size=28, bold=True,\n          color=T.INK, font=T.FONT_DISPLAY)\n    two = len(lines) > 14\n    half = (len(lines) + 1) // 2 if two else len(lines)\n    cols = [lines[:half]] + ([lines[half:]] if two else [])\n    col_w = Inches(5.9) if two else CW\n    for ci, col in enumerate(cols):\n        tb = slide.shapes.add_textbox(ML + Inches(6.2) * ci, Inches(1.55),\n                                      col_w, Inches(5.5))\n        tf = tb.text_frame\n        tf.word_wrap = True\n        for i, (txt, lv) in enumerate(col):\n            p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()\n            p.space_after = Pt(4)\n            p.level = min(lv, 2)\n            r = p.add_run()\n            r.text = txt\n            r.font.size = Pt(14 if lv == 0 else 11)\n            r.font.bold = (lv == 0)\n            r.font.name = T.FONT_DISPLAY if lv == 0 else T.FONT_BODY\n            r.font.color.rgb = _rgb(T.INK if lv <= 1 else T.MUTED)\n    _footer(slide)\n\n\ndef _stat_band(prs, sec):\n    slide = _blank(prs)\n    _rect(slide, 0, 0, SW, Inches(0.12), T.PRIMARY)\n    y = Inches(0.5)\n    if sec.get(\"headline\"):\n        _text(slide, ML, y, CW, Inches(0.9), _clip(sec[\"headline\"], 160),\n              size=24, bold=True, color=T.INK, font=T.FONT_DISPLAY)\n        y = Inches(1.55)\n    stats = sec.get(\"stats\") or []\n    if stats:\n        tw = Inches(2.85)\n        gap = Inches(0.13)\n        for i, s in enumerate(stats[:4]):\n            x = ML + (tw + gap) * i\n            _rect(slide, x, y, tw, Inches(1.6), T.SURFACE_ALT, line=T.BORDER)\n            _rect(slide, x, y, Emu(int(0.06 * EMU_IN)), Inches(1.6), _accent())\n            _text(slide, x + Inches(0.2), y + Inches(0.2), tw - Inches(0.3),\n                  Inches(0.85), str(s.get(\"value\", \"\")), size=40, bold=True,\n                  color=T.PRIMARY, font=T.FONT_DISPLAY)\n            _text(slide, x + Inches(0.2), y + Inches(1.1), tw - Inches(0.3),\n                  Inches(0.4), str(s.get(\"label\", \"\")), size=10, bold=True,\n                  color=T.MUTED)\n        y = y + Inches(1.95)\n    if sec.get(\"body\"):\n        _text(slide, ML, y, CW, Inches(2.4), _clip(sec[\"body\"], 2000), size=14,\n              color=T.INK)\n    _footer(slide)\n\n\ndef _attack_chain(prs, sec):\n    slide, y = _title_slide(prs, \"Cadeia de Ataque\")\n    lanes = sec.get(\"lanes\") or []\n    lane_h = Inches(1.7)\n    box_w = Inches(2.0)\n    arrow_w = Inches(0.35)\n    step = box_w + arrow_w\n    for li, lane in enumerate(lanes[:3]):\n        ly = y + lane_h * li\n        _text(slide, ML, ly, CW, Inches(0.35), _clip(lane.get(\"title\", \"\"), 80),\n              size=12, bold=True, color=T.INK)\n        steps = (lane.get(\"steps\") or [])[:5]\n        for si, st in enumerate(steps):\n            x = ML + step * si\n            by = ly + Inches(0.42)\n            _rect(slide, x, by, box_w, Inches(0.9), T.SURFACE_ALT, line=T.BORDER)\n            _rect(slide, x, by, box_w, Emu(int(0.05 * EMU_IN)), T.PRIMARY)\n            _text(slide, x + Inches(0.1), by + Inches(0.1), box_w - Inches(0.2),\n                  Inches(0.35), _clip(st.get(\"label\", \"\"), 22), size=11,\n                  bold=True, color=T.PRIMARY)\n            if st.get(\"detail\"):\n                _text(slide, x + Inches(0.1), by + Inches(0.45),\n                      box_w - Inches(0.2), Inches(0.42),\n                      _clip(st.get(\"detail\", \"\"), 44), size=8, color=T.MUTED)\n            if si < len(steps) - 1:\n                _text(slide, x + box_w, by + Inches(0.28), arrow_w, Inches(0.4),\n                      \"\u2192\", size=18, bold=True, color=_accent(),\n                      align=PP_ALIGN.CENTER)\n\n\ndef _roadmap(prs, sec):\n    slide, y = _title_slide(prs, \"Plano de Remedia\u00e7\u00e3o por Fase\")\n    phases = sec.get(\"phases\") or []\n    cw = Inches(2.85)\n    gap = Inches(0.13)\n    for i, ph in enumerate(phases[:4]):\n        x = ML + (cw + gap) * i\n        _rect(slide, x, y, cw, Inches(5.0), T.SURFACE_ALT, line=T.BORDER)\n        _rect(slide, x, y, cw, Inches(0.7), T.PRIMARY)\n        _text(slide, x + Inches(0.15), y + Inches(0.08), cw - Inches(0.25),\n              Inches(0.3), ph.get(\"window\", \"\"), size=11, bold=True,\n              color=\"FFFFFF\")\n        _text(slide, x + Inches(0.15), y + Inches(0.38), cw - Inches(0.25),\n              Inches(0.3), ph.get(\"label\", \"\"), size=10, color=\"C9D3E6\")\n        yy = y + Inches(0.9)\n        for a in (ph.get(\"actions\") or [])[:6]:\n            _text(slide, x + Inches(0.15), yy, cw - Inches(0.3), Inches(0.6),\n                  \"\u25b8 \" + _clip(a, 62), size=9, color=T.INK)\n            yy += Inches(0.62)\n\n\ndef _cost_incident(prs, sec):\n    slide, y = _title_slide(prs, \"Custo da Remedia\u00e7\u00e3o \u00d7 Custo do Incidente\")\n    colw = Inches(5.9)\n    gap = Inches(0.33)\n    _rect(slide, ML, y, colw, Inches(5.0), T.SURFACE_ALT, line=T.BORDER)\n    _rect(slide, ML, y, colw, Inches(0.55), T.SUCCESS)\n    _text(slide, ML + Inches(0.2), y + Inches(0.1), colw - Inches(0.3),\n          Inches(0.35), \"REMEDIA\u00c7\u00c3O \u2014 INVESTIMENTO\", size=12, bold=True,\n          color=\"FFFFFF\")\n    yy = y + Inches(0.75)\n    for r in (sec.get(\"remediation\") or [])[:6]:\n        _text(slide, ML + Inches(0.2), yy, colw - Inches(0.4), Inches(0.5),\n              \"\u25c6 \" + _clip(r, 72), size=11, color=T.INK)\n        yy += Inches(0.55)\n    x2 = ML + colw + gap\n    _rect(slide, x2, y, colw, Inches(5.0), T.SURFACE_ALT, line=T.BORDER)\n    _rect(slide, x2, y, colw, Inches(0.55), T.DESTRUCTIVE)\n    _text(slide, x2 + Inches(0.2), y + Inches(0.1), colw - Inches(0.3),\n          Inches(0.35), \"INCIDENTE N\u00c3O REMEDIADO \u2014 RISCO\", size=12, bold=True,\n          color=\"FFFFFF\")\n    yy = y + Inches(0.75)\n    for it in (sec.get(\"incident\") or [])[:4]:\n        _text(slide, x2 + Inches(0.2), yy, colw - Inches(0.4), Inches(0.35),\n              \"\u25c6 \" + _clip(it.get(\"label\", \"\"), 60), size=12, bold=True,\n              color=T.DESTRUCTIVE)\n        yy += Inches(0.38)\n        if it.get(\"detail\"):\n            _text(slide, x2 + Inches(0.45), yy, colw - Inches(0.6), Inches(0.4),\n                  _clip(it.get(\"detail\", \"\"), 72), size=10, color=T.MUTED)\n            yy += Inches(0.55)\n        else:\n            yy += Inches(0.2)\n\n\ndef _partner_value(prs, sec):\n    slide, y = _title_slide(prs, _clip(sec.get(\"title\", \"Parceria\"), 60))\n    pts = sec.get(\"points\") or []\n    cw = Inches(5.9)\n    ch = Inches(2.2)\n    gapx = Inches(0.33)\n    gapy = Inches(0.3)\n    for i, p in enumerate(pts[:4]):\n        col = i % 2\n        row = i // 2\n        x = ML + (cw + gapx) * col\n        yy = y + (ch + gapy) * row\n        _rect(slide, x, yy, cw, ch, T.SURFACE_ALT, line=T.BORDER)\n        _rect(slide, x, yy, Emu(int(0.06 * EMU_IN)), ch, _accent())\n        _text(slide, x + Inches(0.25), yy + Inches(0.15), cw - Inches(0.4),\n              Inches(0.4), _clip(p.get(\"title\", \"\"), 40), size=15, bold=True,\n              color=T.PRIMARY, font=T.FONT_DISPLAY)\n        _text(slide, x + Inches(0.25), yy + Inches(0.6), cw - Inches(0.4),\n              Inches(1.5), _clip(p.get(\"body\", \"\"), 260), size=11, color=T.INK)\n\n\ndef _next_steps(prs, sec):\n    slide, y = _title_slide(prs, \"Pr\u00f3ximos Passos\")\n    steps = sec.get(\"steps\") or []\n    yy = y\n    for i, s in enumerate(steps[:6], 1):\n        _rect(slide, ML, yy, Inches(0.55), Inches(0.55), T.PRIMARY)\n        _text(slide, ML, yy, Inches(0.55), Inches(0.55), str(i), size=20,\n              bold=True, color=\"FFFFFF\", align=PP_ALIGN.CENTER,\n              anchor=MSO_ANCHOR.MIDDLE)\n        _text(slide, ML + Inches(0.75), yy + Inches(0.05), CW - Inches(1.0),\n              Inches(0.5), _clip(s, 110), size=15, color=T.INK,\n              anchor=MSO_ANCHOR.MIDDLE)\n        yy += Inches(0.75)\n    brand = _STATE[\"meta\"].get(\"brand\", {})\n    contact = \" \u00b7 \".join(\n        [x for x in [brand.get(\"name\", \"\"), brand.get(\"contact\", \"\"),\n                     brand.get(\"tagline\", \"\")] if x])\n    _text(slide, ML, Inches(6.4), CW, Inches(0.4), contact, size=11,\n          color=T.MUTED)\n\n\ndef _kpis(prs, kpis):\n    slide, y = _title_slide(prs, \"Indicadores\")\n    tiles = [\n        (\"Total de achados\", str(kpis.get(\"total\", 0)), T.PRIMARY),\n        (\"Risco (0-100)\", str(kpis.get(\"riskScore\", 0)), T.DESTRUCTIVE\n         if kpis.get(\"riskScore\", 0) >= 55 else T.WARNING),\n        (\"CVSS medio\", str(kpis.get(\"avgCvss\") if kpis.get(\"avgCvss\") is not None else \"-\"), T.INK),\n        (\"Criticos+Altos\",\n         str(kpis.get(\"bySeverity\", {}).get(\"critical\", 0) + kpis.get(\"bySeverity\", {}).get(\"high\", 0)),\n         _accent()),\n    ]\n    tw = Inches(2.85)\n    gap = Inches(0.13)\n    for i, (label, val, col) in enumerate(tiles):\n        x = ML + (tw + gap) * i\n        _rect(slide, x, y, tw, Inches(1.7), T.SURFACE_ALT, line=T.BORDER)\n        _rect(slide, x, y, Emu(int(0.06 * EMU_IN)), Inches(1.7), col)\n        _text(slide, x + Inches(0.2), y + Inches(0.2), tw - Inches(0.3), Inches(0.4),\n              label.upper(), size=10, bold=True, color=T.MUTED)\n        _text(slide, x + Inches(0.2), y + Inches(0.6), tw - Inches(0.3), Inches(0.9),\n              val, size=40, bold=True, color=col, font=T.FONT_DISPLAY)\n\n\ndef _severity_chart(prs, data):\n    slide, y = _title_slide(prs, \"Distribui\u00e7\u00e3o por severidade\")\n    dist = data.get(\"severityDistribution\", [])\n    maxc = max([d.get(\"count\", 0) for d in dist] + [1])\n    barmax = Inches(9.0)\n    row_h = Inches(0.62)\n    for i, d in enumerate(dist):\n        sev = d.get(\"severity\")\n        c = d.get(\"count\", 0)\n        yy = y + row_h * i\n        _text(slide, ML, yy, Inches(2.0), Inches(0.5),\n              T.SEVERITY_LABEL.get(sev, sev), size=13, bold=True, color=T.INK,\n              anchor=MSO_ANCHOR.MIDDLE)\n        w = Emu(int(max(0.04, c / maxc) * barmax)) if c > 0 else Emu(int(0.04 * EMU_IN))\n        _rect(slide, ML + Inches(2.2), yy + Inches(0.08), w, Inches(0.42),\n              T.SEVERITY_COLOR.get(sev, T.MUTED))\n        _text(slide, ML + Inches(2.2) + w + Inches(0.1), yy, Inches(1.0), Inches(0.5),\n              str(c), size=13, bold=True, color=T.INK, anchor=MSO_ANCHOR.MIDDLE)\n\n\ndef _risk_matrix(prs, data):\n    slide, y = _title_slide(prs, \"Matriz de risco (probabilidade \u00d7 impacto)\")\n    cells = {(c[\"likelihood\"], c[\"impact\"]): c.get(\"count\", 0)\n             for c in data.get(\"riskMatrix\", [])}\n    n = 5\n    cell = Inches(1.0)\n    x0 = ML + Inches(1.0)\n    y0 = y + Inches(0.1)\n\n    def band(score):\n        if score >= 8:\n            return T.DESTRUCTIVE\n        if score >= 5:\n            return T.WARNING\n        if score >= 3:\n            return \"6F9BF5\"\n        return T.SUCCESS\n    for li in range(n, 0, -1):\n        for im in range(1, n + 1):\n            row = n - li\n            col = im - 1\n            x = x0 + cell * col\n            yy = y0 + cell * row\n            score = li + im\n            _rect(slide, x, yy, cell - Inches(0.05), cell - Inches(0.05), band(score))\n            cnt = cells.get((li, im), 0)\n            if cnt:\n                _text(slide, x, yy, cell - Inches(0.05), cell - Inches(0.05),\n                      str(cnt), size=20, bold=True, color=\"FFFFFF\",\n                      align=PP_ALIGN.CENTER, anchor=MSO_ANCHOR.MIDDLE)\n    _text(slide, x0, y0 + cell * n + Inches(0.05), cell * n, Inches(0.4),\n          \"Probabilidade \u2192\", size=11, color=T.MUTED)\n\n\ndef _finding_card(prs, sec):\n    f = sec[\"finding\"]\n    sev = f.get(\"severity\", \"info\")\n    # Deck de apresenta\u00e7\u00e3o: s\u00f3 cr\u00edt/alto ganham slide dedicado; os demais constam\n    # na tabela de achados (que pagina TODOS). Mant\u00e9m o PPTX enxuto \u2014 DOCX/PDF\n    # seguem detalhando todos os achados.\n    if sev not in (\"critical\", \"high\"):\n        return\n    fl = _Flow(prs, _clip(f.get(\"title\", \"Achado\"), 70))\n    # Faixa de severidade\n    fl.ensure(Inches(0.6))\n    _rect(fl.slide, ML, Emu(fl.y), CW, Inches(0.5),\n          T.SEVERITY_COLOR.get(sev, T.MUTED))\n    _text(fl.slide, ML + Inches(0.15), Emu(fl.y + int(Inches(0.05))), CW,\n          Inches(0.4),\n          f\"{T.SEVERITY_LABEL.get(sev, sev).upper()}  \u00b7  {f.get('ref','')}  \u00b7  {_clip(f.get('affectedAsset',''),70)}\",\n          size=13, bold=True, color=\"FFFFFF\", anchor=MSO_ANCHOR.MIDDLE)\n    fl.space(Inches(0.66))\n    meta = []\n    if f.get(\"weaknessClass\"):\n        meta.append(f\"Classe: {f['weaknessClass']}\")\n    if f.get(\"cvssVector\"):\n        meta.append(f\"CVSS: {f['cvssVector']}\")\n    if f.get(\"cwe\"):\n        meta.append(f\"CWE: {f['cwe']}\")\n    if meta:\n        fl.para(\"   \".join(meta), size=11, color=T.MUTED, after=0.12)\n    for label, key in [(\"Descri\u00e7\u00e3o\", \"description\"), (\"Impacto\", \"impact\"),\n                       (\"Remedia\u00e7\u00e3o\", \"remediation\")]:\n        if f.get(key):\n            fl.heading(label.upper(), size=11)\n            fl.para(f[key], size=12, color=T.INK, after=0.14)\n    if f.get(\"narrative\"):\n        fl.heading(\"NARRATIVA\", size=11)\n        fl.para(f[\"narrative\"], size=12, color=T.INK, after=0.14)\n    if sec.get(\"showPoc\") and f.get(\"reproductionSteps\"):\n        fl.heading(\"REPRODU\u00c7\u00c3O\", size=11)\n        _steps = f[\"reproductionSteps\"]\n        for i, s in enumerate(_steps[:6], 1):\n            fl.para(f\"{i}. {s}\", size=11, color=T.INK, indent=0.1, after=0.04)\n        if len(_steps) > 6:\n            fl.para(\n                f\"(+{len(_steps) - 6} passos \u2014 detalhe completo no relat\u00f3rio t\u00e9cnico DOCX/PDF)\",\n                size=10, color=T.MUTED, indent=0.1, after=0.04)\n    if sec.get(\"showPoc\"):\n        _evidence_flow(fl, f)\n\n\ndef _evidence_flow(fl, f):\n    \"\"\"Cadeia de evid\u00eancia + prints INLINE no fluxo do achado (sem cap). Mostra\n    placeholder vis\u00edvel quando um achado alto/cr\u00edtico n\u00e3o tem imagem.\"\"\"\n    ev = sorted(\n        f.get(\"evidence\") or [],\n        key=lambda e: e.get(\"stepIndex\") if e.get(\"stepIndex\") is not None else 1_000_000,\n    )\n    chain = [e for e in ev\n             if e.get(\"snippet\") or e.get(\"command\") or e.get(\"resultSummary\")]\n    imgs = [e for e in ev if e.get(\"imagePath\")]\n    if chain:\n        fl.heading(\"CADEIA DE EVID\u00caNCIA\", size=11)\n        for i, e in enumerate(chain[:6], 1):\n            n = e.get(\"stepIndex\") or i\n            head = f\"{n}.\"\n            if e.get(\"toolName\"):\n                head += f\"  [{e['toolName']}]\"\n            if e.get(\"label\") and e.get(\"label\") != e.get(\"toolName\"):\n                head += f\"  {e['label']}\"\n            fl.para(head, size=11, bold=True, color=T.PRIMARY, after=0.02)\n            if e.get(\"command\"):\n                fl.para(\"$ \" + str(e[\"command\"]), size=9, color=T.MUTED,\n                        font=T.FONT_MONO, indent=0.12, after=0.02)\n            if e.get(\"snippet\"):\n                fl.para(str(e[\"snippet\"]), size=9, color=T.MUTED,\n                        font=T.FONT_MONO, indent=0.12, after=0.02)\n            if e.get(\"resultSummary\"):\n                fl.para(\"\u2192 prova: \" + str(e[\"resultSummary\"]), size=10,\n                        color=T.SUCCESS, indent=0.12, after=0.08)\n    if len(chain) > 6:\n        fl.para(\n            f\"(+{len(chain) - 6} passos de evid\u00eancia \u2014 cadeia completa no relat\u00f3rio t\u00e9cnico DOCX/PDF)\",\n            size=10, color=T.MUTED, after=0.08)\n    rendered = 0\n    if imgs:\n        fl.heading(\"EVID\u00caNCIA VISUAL\", size=11)\n        for e in imgs[:4]:\n            if fl.image(e.get(\"imagePath\"), e.get(\"label\")):\n                rendered += 1\n            elif f.get(\"severity\") in (\"critical\", \"high\"):\n                fl.placeholder(\n                    \"\u26a0 Evid\u00eancia visual referenciada n\u00e3o dispon\u00edvel no pacote.\")\n        if len(imgs) > 4:\n            fl.para(\n                f\"(+{len(imgs) - 4} imagens \u2014 veja o relat\u00f3rio t\u00e9cnico completo)\",\n                size=10, color=T.MUTED, after=0.08)\n    if rendered == 0 and not imgs and f.get(\"severity\") in (\"critical\", \"high\"):\n        if any(e.get(\"imageUnavailable\") for e in ev):\n            fl.placeholder(\n                \"\u26a0 Evid\u00eancia visual capturada, por\u00e9m indispon\u00edvel (expirada/removida do armazenamento).\")\n        else:\n            fl.placeholder(\"\u26a0 Evid\u00eancia visual n\u00e3o capturada para este achado.\")\n\n\ndef _table(prs, findings, title, remediation=False):\n    # Pagina as linhas em slides \"(cont.)\" \u2014 nenhum achado some (antes: [:12]).\n    ROWS_PER = 13\n    chunks = [findings[i:i + ROWS_PER]\n              for i in range(0, len(findings), ROWS_PER)] or [[]]\n    if remediation:\n        headers = [\"Ref\", \"Sev\", \"Ativo\", \"Remediacao\"]\n        widths = [Inches(1.2), Inches(1.4), Inches(3.5), Inches(6.0)]\n    else:\n        headers = [\"Ref\", \"Sev\", \"Titulo\", \"Ativo\"]\n        widths = [Inches(1.2), Inches(1.4), Inches(5.5), Inches(4.0)]\n    for ci, chunk in enumerate(chunks):\n        slide, y = _title_slide(\n            prs, title if ci == 0 else _clip(title, 58) + \" (cont.)\")\n        rows = len(chunk) + 1\n        gt = slide.shapes.add_table(rows, len(headers), ML, y, CW,\n                                    Inches(0.4) * rows).table\n        for j, hd in enumerate(headers):\n            gt.columns[j].width = widths[j]\n            cell = gt.cell(0, j)\n            cell.fill.solid()\n            cell.fill.fore_color.rgb = _rgb(T.PRIMARY)\n            # add_run() sempre cria um run \u2014 ao contr\u00e1rio de `cell.text = \"\"`,\n            # que deixa o par\u00e1grafo SEM run e faz runs[0] estourar IndexError.\n            pr = cell.text_frame.paragraphs[0].add_run()\n            pr.text = str(hd)\n            pr.font.size = Pt(11)\n            pr.font.bold = True\n            pr.font.color.rgb = _rgb(\"FFFFFF\")\n        for i, f in enumerate(chunk, start=1):\n            sev = f.get(\"severity\", \"info\")\n            vals = ([f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                     _clip(f.get(\"affectedAsset\", \"\"), 44),\n                     _clip(f.get(\"remediation\", \"\"), 140)]\n                    if remediation else\n                    [f.get(\"ref\", \"\"), T.SEVERITY_LABEL.get(sev, sev),\n                     _clip(f.get(\"title\", \"\"), 80),\n                     _clip(f.get(\"affectedAsset\", \"\"), 44)])\n            for j, v in enumerate(vals):\n                cell = gt.cell(i, j)\n                # add_run() tolera valor vazio (achado sem remediation/ref/ativo).\n                r = cell.text_frame.paragraphs[0].add_run()\n                r.text = str(v)\n                r.font.size = Pt(10)\n                r.font.color.rgb = _rgb(\n                    T.SEVERITY_COLOR.get(sev, T.INK) if j == 1 else T.INK)\n                if j == 1:\n                    r.font.bold = True\n\n\ndef _bullets(prs, items, title):\n    fl = _Flow(prs, title or \"Itens\")\n    for it in items:\n        fl.para(\"\u2022  \" + str(it), size=14, color=T.INK, after=0.09)\n\n\ndef _paragraph(prs, text, title):\n    fl = _Flow(prs, title or \"\")\n    fl.para(text, size=15, color=T.INK)\n\n\ndef _callout(prs, sec, title):\n    slide, y = _title_slide(prs, title or \"\")\n    col = T.CALLOUT_COLOR.get(sec.get(\"tone\", \"info\"), T.PRIMARY)\n    _rect(slide, ML, y, CW, Inches(1.2), T.SURFACE_ALT, line=T.BORDER)\n    _rect(slide, ML, y, Emu(int(0.08 * EMU_IN)), Inches(1.2), col)\n    _text(slide, ML + Inches(0.3), y + Inches(0.15), CW - Inches(0.5), Inches(0.9),\n          _clip(sec.get(\"text\", \"\"), 400), size=16, bold=True, color=col,\n          anchor=MSO_ANCHOR.MIDDLE)\n\n\ndef _apply_brand(meta):\n    brand = meta.get(\"brand\") or {}\n    if brand.get(\"primary\"):\n        T.PRIMARY = brand[\"primary\"]\n    if brand.get(\"accent\"):\n        T.CORAL = brand[\"accent\"]\n    if brand.get(\"wordmark\"):\n        T.WORDMARK = brand[\"wordmark\"]\n\n\ndef render_pptx(model, out_path):\n    prs = Presentation()\n    prs.slide_width = SW\n    prs.slide_height = SH\n    meta = model.get(\"meta\", {})\n    _STATE[\"meta\"] = meta\n    _STATE[\"page\"] = 0\n    _apply_brand(meta)\n    title = None\n    _agenda_entries = []\n    for s in model.get(\"sections\", []):\n        _st = s.get(\"type\")\n        if _st == \"partDivider\":\n            _agenda_entries.append((s.get(\"title\", \"\"), 0))\n        elif _st == \"heading\" and s.get(\"level\", 1) in (1, 2):\n            _agenda_entries.append((s.get(\"text\", \"\"), s.get(\"level\", 1)))\n    for sec in model.get(\"sections\", []):\n        t = sec.get(\"type\")\n        if t == \"cover\":\n            _cover(prs, sec, meta)\n            _agenda(prs, _agenda_entries, meta)\n        elif t == \"partDivider\":\n            _part_divider(prs, sec)\n        elif t == \"divider\":\n            _divider(prs, meta)\n        elif t == \"heading\":\n            title = sec.get(\"text\")\n        elif t == \"statBand\":\n            _stat_band(prs, sec)\n        elif t == \"kpis\":\n            _kpis(prs, sec.get(\"kpis\", {}))\n        elif t == \"severityChart\":\n            _severity_chart(prs, sec.get(\"data\", {}))\n        elif t == \"riskMatrix\":\n            _risk_matrix(prs, sec.get(\"data\", {}))\n        elif t == \"attackChain\":\n            _attack_chain(prs, sec)\n        elif t == \"findingCard\":\n            _finding_card(prs, sec)\n        elif t == \"findingsTable\":\n            _table(prs, sec.get(\"findings\", []), title or \"Sum\u00e1rio de Achados\")\n        elif t == \"remediationMatrix\":\n            _table(prs, sec.get(\"findings\", []), title or \"Matriz de Remedia\u00e7\u00e3o\", remediation=True)\n        elif t == \"roadmap\":\n            _roadmap(prs, sec)\n        elif t == \"costVsIncident\":\n            _cost_incident(prs, sec)\n        elif t == \"partnerValue\":\n            _partner_value(prs, sec)\n        elif t == \"nextSteps\":\n            _next_steps(prs, sec)\n        elif t == \"bullets\":\n            _bullets(prs, sec.get(\"items\", []), title)\n        elif t == \"paragraph\":\n            _paragraph(prs, sec.get(\"text\", \"\"), title)\n        elif t == \"callout\":\n            _callout(prs, sec, title)\n    prs.save(out_path)\n",
  "render_report.py": "\"\"\"Entry do renderer de relatorio.\n\nUso: python render_report.py <model.json> <docx|pptx|pdf|json> <out_path>\n\nLe um ReportModel (JSON, ver lib/reports/report-model.ts) e gera o arquivo no\nformato pedido. `json` reemite o proprio ReportModel (estruturado, legivel por\nmaquina) \u2014 nenhuma dependencia de terceiros. Sem dependencia de rede; roda num\ncontainer controlado (E2B dedicado na v1 do trigger, ou @trigger.dev/python na\nv2).\"\"\"\n\nimport sys\nimport os\nimport json\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\n\ndef main():\n    if len(sys.argv) < 4:\n        raise SystemExit(\n            \"uso: render_report.py <model.json> <docx|pptx|pdf|json> <out>\"\n        )\n    model_path, fmt, out_path = sys.argv[1], sys.argv[2], sys.argv[3]\n    with open(model_path, encoding=\"utf-8\") as f:\n        model = json.load(f)\n    if fmt == \"pptx\":\n        from pptx_renderer import render_pptx\n\n        render_pptx(model, out_path)\n    elif fmt == \"docx\":\n        from docx_renderer import render_docx\n\n        render_docx(model, out_path)\n    elif fmt == \"pdf\":\n        from pdf_renderer import render_pdf\n\n        render_pdf(model, out_path)\n    elif fmt == \"json\":\n        # Exportacao estruturada: o proprio ReportModel (meta + kpis + charts +\n        # sections, com os achados/evidencias embutidos). Sem truncar.\n        with open(out_path, \"w\", encoding=\"utf-8\") as fh:\n            json.dump(model, fh, ensure_ascii=False, indent=2)\n    else:\n        raise SystemExit(f\"formato invalido: {fmt}\")\n    print(f\"OK {fmt} -> {out_path}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "theme.py": "\"\"\"Tokens de marca do relatorio (espelham lib/reports/theme.ts / app globals.css).\n\nHex SEM '#'. Fontes: usa-se Calibri (presente em Word/PowerPoint) para body e\ntitulos por seguranca de renderizacao no cliente; a marca vem sobretudo da\nPALETA (azul/coral) e do layout. A tipografia da marca e IBM Plex (OFL),\nembutida nos .ttf em fonts/ (ver FONT_* e font_path() abaixo).\n\"\"\"\n\nimport os\n\nPRIMARY = \"2456E6\"\nCORAL = \"FF7678\"\nINK = \"0E1B2E\"\nMUTED = \"5B6B84\"\nSURFACE = \"FFFFFF\"\nSURFACE_ALT = \"F4F7FC\"\nBORDER = \"E2E8F5\"\nSUCCESS = \"12996B\"\nWARNING = \"C9820B\"\nDESTRUCTIVE = \"DA2C3C\"\n\n# Bloco de evidencia estilo \"terminal\" (modelo-ouro SYN): fundo navy escuro +\n# texto MONO colorido (cores claras p/ contraste no escuro).\nEV_BG = \"0B1424\"   # fundo do bloco (navy quase preto)\nEV_CMD = \"9FE2FF\"  # comando / request (ciano)\nEV_OK = \"5FD69A\"   # resultado OK / prova (verde)\nEV_CRIT = \"FFD27A\"  # valor critico / dado sensivel (ambar)\nEV_OUT = \"D6E2F0\"  # output neutro\nEV_META = \"7C93A8\"  # comentario / metadado (cabecalho do passo)\n\nCHART = [\"2456E6\", \"3F6EF0\", \"6F9BF5\", \"12996B\", \"C9820B\"]\n\nSEVERITY_COLOR = {\n    \"critical\": \"DA2C3C\",\n    \"high\": \"E8590C\",\n    \"medium\": \"C9820B\",\n    \"low\": \"2456E6\",\n    \"info\": \"5B6B84\",\n}\nSEVERITY_LABEL = {\n    \"critical\": \"Critico\",\n    \"high\": \"Alto\",\n    \"medium\": \"Medio\",\n    \"low\": \"Baixo\",\n    \"info\": \"Informativo\",\n}\nSEVERITY_ORDER = [\"critical\", \"high\", \"medium\", \"low\", \"info\"]\n\nCALLOUT_COLOR = {\n    \"info\": PRIMARY,\n    \"warning\": WARNING,\n    \"critical\": DESTRUCTIVE,\n    \"success\": SUCCESS,\n}\n\n# Tipografia da marca: IBM Plex (OFL). O PDF (reportlab) EMBUTE os glifos dos\n# .ttf em fonts/; DOCX/PPTX referenciam o NOME da familia (o embed real no\n# pacote OOXML e follow-up, com validacao via Office/COM). Sem os .ttf\n# presentes, os renderers caem para Calibri/Helvetica.\nFONT_DISPLAY = \"IBM Plex Sans\"\nFONT_BODY = \"IBM Plex Sans\"\nFONT_MONO = \"IBM Plex Mono\"\n\n_FONT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), \"fonts\")\n_FONT_FILES = {\n    (\"IBM Plex Sans\", \"normal\"): \"IBMPlexSans-Regular.ttf\",\n    (\"IBM Plex Sans\", \"bold\"): \"IBMPlexSans-Bold.ttf\",\n    (\"IBM Plex Mono\", \"normal\"): \"IBMPlexMono-Regular.ttf\",\n}\n\n\ndef font_path(family, variant=\"normal\"):\n    \"\"\"Caminho absoluto do .ttf (ou None se ausente). Resolve tanto no sandbox\n    E2B (fonts/ ao lado dos .py) quanto nos testes locais.\"\"\"\n    fn = _FONT_FILES.get((family, variant))\n    if not fn:\n        return None\n    p = os.path.join(_FONT_DIR, fn)\n    return p if os.path.exists(p) else None\n\nWORDMARK = \"Suricatoos\"\n\n\ndef cover_fit(src, tw, th):\n    \"\"\"Crop-to-fill: recorta a imagem (centro) ao aspecto tw:th, preenchendo o\n    alvo SEM distorcer. Retorna um .png tempor\u00e1rio; em falha, devolve `src`.\n    Usado pela capa dos 3 renderers (antes esticavam a arte \u2192 distor\u00e7\u00e3o/estouro).\"\"\"\n    try:\n        from PIL import Image\n        import tempfile\n        im = Image.open(src).convert(\"RGB\")\n        iw, ih = im.size\n        ta = float(tw) / float(th)\n        ia = (iw / ih) if ih else ta\n        if ia > ta:  # imagem mais larga \u2192 corta laterais\n            nw = max(1, int(round(ih * ta)))\n            x = (iw - nw) // 2\n            im = im.crop((x, 0, x + nw, ih))\n        elif ia < ta:  # imagem mais alta \u2192 corta topo/base\n            nh = max(1, int(round(iw / ta)))\n            y = (ih - nh) // 2\n            im = im.crop((0, y, iw, y + nh))\n        fd, out = tempfile.mkstemp(suffix=\".png\")\n        os.close(fd)\n        im.save(out, \"PNG\")\n        return out\n    except Exception:\n        return src\n\n\ndef default_cover_bg():\n    \"\"\"Fundo navy PADR\u00c3O da capa quando a marca N\u00c3O tem arte pr\u00f3pria \u2014 padr\u00e3o-ouro\n    SYN. Em vez de uma capa clara, a capa nasce navy: navy s\u00f3lido (INK) + faixa\n    fina azul (PRIMARY) no topo + tra\u00e7o coral (CORAL). Retrato ~US Letter (0.773),\n    cacheado no tempdir; regenerado a cada chamada p/ refletir overrides de marca.\n    Retorna o caminho do PNG; o chamador o trata como `coverImagePath` (full-bleed,\n    t\u00edtulo/logo/KPIs em branco).\"\"\"\n    import tempfile\n    from PIL import Image, ImageDraw\n\n    def _t(h):\n        return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))\n\n    out = os.path.join(tempfile.gettempdir(), \"suricatoos_cover_default_navy.png\")\n    W, H = 1700, 2200\n    img = Image.new(\"RGB\", (W, H), _t(INK))\n    d = ImageDraw.Draw(img)\n    # Faixa fina azul no topo (sem texto por cima) \u2014 unico acento no fundo.\n    # (Sem traco coral fixo no meio: a posicao do texto varia por renderer e o\n    # traco cruzaria o titulo/classificacao em alguns; o acento coral ja vem da\n    # linha de classificacao, que e CORAL.)\n    d.rectangle([0, 0, W, 24], fill=_t(PRIMARY))\n    img.save(out, \"PNG\")\n    return out\n",
};
